    /**
     * Scans equipped items and returns a map of item IDs to their counts.
     * Equipped items are counted as 1 each (equipment slots can only hold 1 item).
     * Uses EquipmentInventorySlot with ItemContainer for reliable detection of all
     * equipped items,
     * including rings and other items that may not be detected by
     * PlayerComposition.
     */
    private Map<Integer, Integer> getEquippedItems() {
        Map<Integer, Integer> equippedItems = new HashMap<>();

        // Get the equipment ItemContainer using the equipment container ID
        // Equipment container ID is 94 in RuneLite
        ItemContainer equipment = client.getItemContainer(94);
        if (equipment == null) {
            return equippedItems;
        }

        Item[] items = equipment.getItems();
        if (items == null) {
            return equippedItems;
        }

        // Iterate through all EquipmentInventorySlot values to check each slot
        for (EquipmentInventorySlot slot : EquipmentInventorySlot.values()) {
            try {
                int slotIdx = slot.getSlotIdx();
                // Ensure the slot index is within bounds
                if (slotIdx >= 0 && slotIdx < items.length) {
                    Item item = items[slotIdx];
                    if (item != null && item.getId() > 0) {
                        int itemId = item.getId();
                        // Count each equipped item as 1
                        equippedItems.put(itemId, equippedItems.getOrDefault(itemId, 0) + 1);
                    }
                }
            } catch (Exception e) {
                // Skip invalid slots gracefully
                continue;
            }
        }

        return equippedItems;
    }

    public Map<Integer, Integer> itemsToCheck;

    @Override
    public Dimension render(Graphics2D graphics) {
        // Clean up InfoBoxes if overlay is inactive
        if (!plugin.isOverlayActive()) {
            clearAllInfoBoxes();
            return null;
        }

        if (!plugin.areItemsCollected()) {
            // List of items to check
            Map<Integer, Integer> itemsToCheck = null;
            if (plugin.getFarmingTeleportOverlay().isCustomRunMode()
                    && !plugin.getFarmingTeleportOverlay().getCustomRunLocations().isEmpty()) {
                itemsToCheck = CustomRunItemRequirements.buildRequirements(
                        plugin.getLocationCatalog(),
                        plugin.getConfig(),
                        client,
                        plugin.getFarmingTeleportOverlay().getCustomRunLocations(),
                        plugin.getCustomRunIncludeSecateurs(),
                        plugin.getCustomRunIncludeDibber(),
                        plugin.getCustomRunIncludeRake());
            }
            if (itemsToCheck == null) {
                return null;
            }

            ItemContainer inventory = client.getItemContainer(InventoryID.INV);

            Item[] items;
            if (inventory == null || inventory.getItems() == null) {
                items = new Item[0];
            } else {
                items = inventory.getItems();
            }

            // Build expanded rune map once before any requirement checks
            Map<Integer, Integer> expandedRuneMap = buildExpandedRuneMap(items);

            int teleportCrystalCount = 0;
            for (Item item : items) {
                if (isTeleportCrystal(item.getId())) {
                    teleportCrystalCount += item.getQuantity();
                }
            }
            int skillsNecklaceCharges = 0;
            // Count charges from inventory
            for (Item item : items) {
                if (isSkillsNecklace(item.getId())) {
                    int charges = getSkillsNecklaceCharges(item.getId());
                    skillsNecklaceCharges += charges * item.getQuantity();
                }
            }
            // Count charges from equipped items
            Map<Integer, Integer> equippedItems = getEquippedItems();
            for (Map.Entry<Integer, Integer> equippedEntry : equippedItems.entrySet()) {
                int equippedItemId = equippedEntry.getKey();
                if (isSkillsNecklace(equippedItemId)) {
                    int charges = getSkillsNecklaceCharges(equippedItemId);
                    skillsNecklaceCharges += charges;
                }
            }
            int necklaceOfPassageCharges = 0;
            for (Item item : items) {
                if (isNecklaceOfPassage(item.getId())) {
                    necklaceOfPassageCharges += getNecklaceOfPassageCharges(item.getId()) * item.getQuantity();
                }
            }
            for (Map.Entry<Integer, Integer> equippedEntry : equippedItems.entrySet()) {
                int equippedItemId = equippedEntry.getKey();
                if (isNecklaceOfPassage(equippedItemId)) {
                    necklaceOfPassageCharges += getNecklaceOfPassageCharges(equippedItemId);
                }
            }
            int quetzalWhistleCount = 0;
            for (Item item : items) {
                if (isQuetzalWhistle(item.getId())) {
                    quetzalWhistleCount += item.getQuantity();
                }
            }
            int combatBraceletCharges = 0;
            for (Item item : items) {
                if (isCombatBracelet(item.getId())) {
                    int charges = Constants.getCombatBraceletCharges(item.getId());
                    combatBraceletCharges += charges * item.getQuantity();
                }
            }
            for (Map.Entry<Integer, Integer> equippedEntry : equippedItems.entrySet()) {
                if (isCombatBracelet(equippedEntry.getKey())) {
                    combatBraceletCharges += Constants.getCombatBraceletCharges(equippedEntry.getKey());
                }
            }

            int totalSeeds = 0;
            int totalAllotmentSeeds = 0;
            int totalTreeSaplings = 0;
            int totalFruitTreeSaplings = 0;
            int totalHopsSeeds = 0;
            int totalFlowerSeeds = 0;
            boolean customRun = plugin.getFarmingTeleportOverlay().isCustomRunMode();
            // First-class Seed Box state: null container = unknown; non-null = known (possibly empty).
            boolean seedBoxContentsUnknown = inventoryContainsSeedBox(items) && !isSeedBoxContentsKnown();
            Item[] seedBoxItems = getSeedBoxItems();
            if (customRun) {
                for (Item item : items) {
                    if (isHerbSeed(item.getId())) {
                        totalSeeds += item.getQuantity();
                    }
                    if (isAllotmentSeed(item.getId())) {
                        totalAllotmentSeeds += item.getQuantity();
                    }
                    if (isFlowerSeed(item.getId())) {
                        totalFlowerSeeds += item.getQuantity();
                    }
                }
                for (Item item : seedBoxItems) {
                    if (item == null) {
                        continue;
                    }
                    if (isHerbSeed(item.getId())) {
                        totalSeeds += item.getQuantity();
                    }
                    if (isAllotmentSeed(item.getId())) {
                        totalAllotmentSeeds += item.getQuantity();
                    }
                    if (isFlowerSeed(item.getId())) {
                        totalFlowerSeeds += item.getQuantity();
                    }
                }
            }
            if (customRun) {
                for (Item item : items) {
                    if (isTreeSapling(item.getId())) {
                        totalTreeSaplings += item.getQuantity();
                    }
                }
            }
            if (customRun) {
                for (Item item : items) {
                    if (isFruitTreeSapling(item.getId())) {
                        totalFruitTreeSaplings += item.getQuantity();
                    }
                }
            }
            if (customRun) {
                for (Item item : items) {
                    if (isHopsSeed(item.getId())) {
                        totalHopsSeeds += item.getQuantity();
                    }
                }
                for (Item item : seedBoxItems) {
                    if (item != null && isHopsSeed(item.getId())) {
                        totalHopsSeeds += item.getQuantity();
                    }
                }
            }

            panelComponent.getChildren().clear();

            // Single inventory scan to build comprehensive item count map (including rune
            // pouch expansions)
            Map<Integer, Integer> inventoryItemCounts = new HashMap<>();
            boolean hasRunePouch = false;

            // First pass: scan inventory for regular items and check for rune pouch
            for (Item item : items) {
                if (item != null) {
                    int itemId = item.getId();
                    int itemQuantity = item.getQuantity();

                    // Check if this is a rune pouch
                    if (RUNE_POUCH_ID.contains(itemId)) {
                        hasRunePouch = true;
                    }

                    if (COMBINATION_RUNE_SUBRUNES_MAP.containsKey(itemId)) {
                        // Handle combination runes
                        List<Integer> subRunes = COMBINATION_RUNE_SUBRUNES_MAP.get(itemId);
                        for (int subRune : subRunes) {
                            inventoryItemCounts.put(subRune,
                                    inventoryItemCounts.getOrDefault(subRune, 0) + itemQuantity);
                        }
                    } else if (STAFF_RUNES_MAP.containsKey(itemId)) {
                        // Handle staffs - add their runes with large amount
                        List<Integer> staffRunes = STAFF_RUNES_MAP.get(itemId);
                        for (int rune : staffRunes) {
                            // Use max to ensure we always have enough, but cap at STAFF_RUNE_AMOUNT to
                            // avoid overflow
                            inventoryItemCounts.put(rune,
                                    Math.max(inventoryItemCounts.getOrDefault(rune, 0), STAFF_RUNE_AMOUNT));
                        }
                    } else {
                        // Handle regular items - sum quantities across slots (e.g. multiple compost)
                        inventoryItemCounts.put(itemId, inventoryItemCounts.getOrDefault(itemId, 0) + itemQuantity);
                    }
                }
            }

            // Second pass: if rune pouch exists, add expanded rune map contents to
            // inventory counts
            if (hasRunePouch) {
                for (Map.Entry<Integer, Integer> runeEntry : expandedRuneMap.entrySet()) {
                    int runeId = runeEntry.getKey();
                    int runeCount = runeEntry.getValue();
                    inventoryItemCounts.put(runeId, inventoryItemCounts.getOrDefault(runeId, 0) + runeCount);
                }
            }

            // Seed box contents (InventoryID.SEED_BOX) count toward seed requirements
            for (Item seedBoxItem : seedBoxItems) {
                if (seedBoxItem == null || seedBoxItem.getId() < 0) {
                    continue;
                }
                int seedBoxItemId = seedBoxItem.getId();
                int seedBoxQty = seedBoxItem.getQuantity();
                inventoryItemCounts.put(seedBoxItemId,
                        inventoryItemCounts.getOrDefault(seedBoxItemId, 0) + seedBoxQty);
            }

            // Third pass: add equipped items to inventory counts
            // Note: equippedItems was already retrieved above for skills necklace charges
            for (Map.Entry<Integer, Integer> equippedEntry : equippedItems.entrySet()) {
                int equippedItemId = equippedEntry.getKey();
                int equippedCount = equippedEntry.getValue();

                // Check if equipped item is a staff
                if (STAFF_RUNES_MAP.containsKey(equippedItemId)) {
                    // Handle staffs - add their runes with large amount
                    List<Integer> staffRunes = STAFF_RUNES_MAP.get(equippedItemId);
                    for (int rune : staffRunes) {
                        // Use max to ensure we always have enough, but cap at STAFF_RUNE_AMOUNT to avoid overflow
                        inventoryItemCounts.put(rune,
                                Math.max(inventoryItemCounts.getOrDefault(rune, 0), STAFF_RUNE_AMOUNT));
                    }
                } else {
                    // Handle regular equipped items
                    inventoryItemCounts.put(equippedItemId,
                            inventoryItemCounts.getOrDefault(equippedItemId, 0) + equippedCount);
                }
            }

            List<AbstractMap.SimpleEntry<Integer, Integer>> missingItemsWithCounts = new ArrayList<>();
            boolean allItemsCollected = true;
            boolean unmetSeedRequirement = false;
            for (Map.Entry<Integer, Integer> entry : itemsToCheck.entrySet()) {
                int itemId = entry.getKey();
                int count = entry.getValue();

                // Start with inventory count from single scan
                int inventoryCount = inventoryItemCounts.getOrDefault(itemId, 0);

                // Lunar staff (9084) satisfies dramen staff requirement for fairy rings
                if (itemId == ItemID.DRAMEN_STAFF) {
                    int lunarCount = inventoryItemCounts.getOrDefault(ItemID.LUNAR_MOONCLAN_LIMINAL_STAFF, 0);
                    inventoryCount += lunarCount;
                }

                // Special handling for bottomless compost bucket - check for filled variants in inventory
                if (itemId == ItemID.BOTTOMLESS_COMPOST_BUCKET) {
                    // Check inventory for any bottomless bucket variant (empty or filled)
                    for (Item item : items) {
                        if (item != null && Constants.BOTTOMLESS_COMPOST_BUCKET_ITEM_IDS.contains(item.getId())) {
                            inventoryCount = 1;
                            break;
                        }
                    }
                }

                // Add tool lep count
                int toolLepCount = checkToolLep(itemId);
                if (toolLepCount > 0) {
                    inventoryCount += toolLepCount;
                }

                // Apply run-specific and item-specific overrides in order
                if (customRun && itemId == BASE_SEED_ID) {
                    inventoryCount = totalSeeds;
                } else if (customRun && itemId == ItemID.LIMPWURT_SEED) {
                    inventoryCount = totalFlowerSeeds;
                } else if (customRun && itemId == BASE_ALLOTMENT_SEED_ID) {
                    inventoryCount = totalAllotmentSeeds;
                } else if (customRun && itemId == BASE_SAPLING_ID) {
                    inventoryCount = totalTreeSaplings;
                } else if (customRun && itemId == BASE_FRUIT_SAPLING_ID) {
                    inventoryCount = totalFruitTreeSaplings;
                } else if (customRun && itemId == BASE_HOPS_SEED_ID) {
                    inventoryCount = totalHopsSeeds;
                } else if (itemId == BASE_TELEPORT_CRYSTAL_ID) {
                    inventoryCount = teleportCrystalCount;
                } else if (itemId == BASE_SKILLS_NECKLACE_ID) {
                    // Skills necklace requirement is in charges, not number of items
                    inventoryCount = skillsNecklaceCharges;
                } else if (itemId == BASE_NECKLACE_OF_PASSAGE_ID) {
                    inventoryCount = necklaceOfPassageCharges;
                } else if (itemId == ItemID.HG_QUETZALWHISTLE_BASIC) {
                    inventoryCount = quetzalWhistleCount;
                } else if (itemId == BASE_EXPLORERS_RING_ID) {
                    // Check if any Explorer's Ring variant is equipped or in inventory
                    // First check inventoryItemCounts (includes equipped items from third pass)
                    // Then also directly check equippedItems as a fallback to ensure detection
                    boolean hasExplorersRing = false;
                    for (int ringId : EXPLORERS_RING_IDS) {
                        // Check in inventoryItemCounts first
                        if (inventoryItemCounts.containsKey(ringId) && inventoryItemCounts.get(ringId) > 0) {
                            hasExplorersRing = true;
                            break;
                        }
                        // Also directly check equipped items as fallback
                        if (equippedItems.containsKey(ringId) && equippedItems.get(ringId) > 0) {
                            hasExplorersRing = true;
                            break;
                        }
                    }
                    inventoryCount = hasExplorersRing ? 1 : 0;
                } else if (itemId == BASE_ARDY_CLOAK_ID) {
                    // Check if any Ardougne Cloak variant is equipped or in inventory
                    // inventoryItemCounts already includes equipped items from the third pass
                    boolean hasArdyCloak = false;
                    for (int cloakId : ARDY_CLOAK_IDS) {
                        if (inventoryItemCounts.containsKey(cloakId) && inventoryItemCounts.get(cloakId) > 0) {
                            hasArdyCloak = true;
                            break;
                        }
                    }
                    inventoryCount = hasArdyCloak ? 1 : 0;
                } else if (itemId == BASE_FARMING_CAPE_ID) {
                    // Check if any Farming cape variant (untrimmed or trimmed) is equipped or in inventory
                    // inventoryItemCounts already includes equipped items from the third pass
                    boolean hasFarmingCape = false;
                    for (int capeId : FARMING_CAPE_IDS) {
                        if (inventoryItemCounts.containsKey(capeId) && inventoryItemCounts.get(capeId) > 0) {
                            hasFarmingCape = true;
                            break;
                        }
                    }
                    inventoryCount = hasFarmingCape ? 1 : 0;
                } else if (itemId == BASE_WATERING_CAN_ID) {
                    // Check if any watering can variant is equipped or in inventory
                    // inventoryItemCounts already includes equipped items from the third pass
                    boolean hasWateringCan = false;
                    for (int canId : WATERING_CAN_IDS) {
                        if (inventoryItemCounts.containsKey(canId) && inventoryItemCounts.get(canId) > 0) {
                            hasWateringCan = true;
                            break;
                        }
                    }
                    inventoryCount = hasWateringCan ? 1 : 0;
                } else if (itemId == BASE_COMBAT_BRACELET_ID) {
                    // Requirement is CHARGES, not number of bracelets. Sum charges from all bracelets.
                    inventoryCount = combatBraceletCharges;
                } else if (itemId == ItemID.PENDANT_OF_ATES) {
                    boolean hasPendant = inventoryItemCounts.getOrDefault(ItemID.PENDANT_OF_ATES, 0) > 0;
                    inventoryCount = hasPendant ? count : 0;
                }

                // Rune pouch contents are already included in inventoryItemCounts
                // Seed box contents are already included in inventoryItemCounts / seed totals
                // (when unknown, getSeedBoxItems() is empty so totals are inventory-only)

                if (inventoryCount < count) {
                    allItemsCollected = false;
                    if (isSeedRequirementItemId(itemId)) {
                        unmetSeedRequirement = true;
                        // Contents may be in the Seed Box — defer seed missing-UI until known.
                        if (seedBoxContentsUnknown) {
                            continue;
                        }
                    }
                    int missingCount = count - inventoryCount;
                    BufferedImage itemImage = itemManager.getImage(itemId);
                    if (itemImage != null) {
                        // Add the missing item and count to the list
                        missingItemsWithCounts.add(new AbstractMap.SimpleEntry<>(itemId, missingCount));
                    }
                }
            }

            // Prompt Check only when the box is present/unknown AND the requirement pass
            // already found unmet seed requirements (no parallel recount).
            boolean promptCheckSeedBox = seedBoxContentsUnknown && unmetSeedRequirement;
            if (promptCheckSeedBox) {
                plugin.addTextToInfoBox("Check the Seed Box to read its contents");
                highlightSeedBoxInInventory(graphics, items);
                allItemsCollected = false;
            } else {
                plugin.addTextToInfoBox("Grab all the items needed");
            }

            // Sort missing items: tools first, then teleport items (basalts last among
            // teleports), then consumable supplies
            missingItemsWithCounts.sort((entry1, entry2) -> {
                int itemId1 = entry1.getKey();
                int itemId2 = entry2.getKey();

                // Get priority: 0 = tools, 1 = regular teleport, 2 = basalt, 3 = consumable
                int priority1 = getItemPriority(itemId1);
                int priority2 = getItemPriority(itemId2);

                // Compare priorities
                return Integer.compare(priority1, priority2);
            });

            plugin.setTeleportOverlayActive(allItemsCollected);

            // Update InfoBoxes - remove ones that are no longer needed, add/update ones
            // that are
            Set<Integer> currentMissingItemIds = new HashSet<>();
            for (AbstractMap.SimpleEntry<Integer, Integer> pair : missingItemsWithCounts) {
                currentMissingItemIds.add(pair.getKey());
            }

            // Remove InfoBoxes for items that are no longer missing
            if (infoBoxManager != null) {
                Iterator<Map.Entry<Integer, RequiredItemInfoBox>> iterator = currentInfoBoxes.entrySet().iterator();
                while (iterator.hasNext()) {
                    Map.Entry<Integer, RequiredItemInfoBox> entry = iterator.next();
                    int itemId = entry.getKey();
                    if (!currentMissingItemIds.contains(itemId)) {
                        infoBoxManager.removeInfoBox(entry.getValue());
                        iterator.remove();
                    }
                }
            }

            // Add or update InfoBoxes for missing items
            if (infoBoxManager != null) {
                for (AbstractMap.SimpleEntry<Integer, Integer> pair : missingItemsWithCounts) {
                    int itemId = pair.getKey();
                    int missingCount = pair.getValue();

                    BufferedImage itemImage = itemManager.getImage(itemId);
                    if (itemImage != null) {
                        String itemName = itemManager.getItemComposition(itemId).getName();
                        if (isTreeSapling(itemId)) {
                            itemName = missingCount == 1 ? "tree sapling" : "tree saplings";
                        } else if (isFruitTreeSapling(itemId)) {
                            itemName = missingCount == 1 ? "fruit tree sapling" : "fruit tree saplings";
                        } else if (isHerbSeed(itemId)) {
                            itemName = missingCount == 1 ? "herb seed" : "herb seeds";
                        } else if (isFlowerSeed(itemId)) {
                            itemName = missingCount == 1 ? "flower seed" : "flower seeds";
                        } else if (isAllotmentSeed(itemId)) {
                            itemName = missingCount == 1 ? "allotment seed" : "allotment seeds";
                        } else if (isHopsSeed(itemId)) {
                            itemName = missingCount == 1 ? "hops seed" : "hops seeds";
                        }
                        RequiredItemInfoBox existingInfoBox = currentInfoBoxes.get(itemId);
                        if (existingInfoBox != null) {
                            // Update existing InfoBox if count changed
                            if (existingInfoBox.getMissingCount() != missingCount) {
                                infoBoxManager.removeInfoBox(existingInfoBox);
                                RequiredItemInfoBox newInfoBox = new RequiredItemInfoBox(itemImage, plugin, itemId,
                                        missingCount, itemName);
                                infoBoxManager.addInfoBox(newInfoBox);
                                currentInfoBoxes.put(itemId, newInfoBox);
                            }
                        } else {
                            // Create new InfoBox
                            RequiredItemInfoBox infoBox = new RequiredItemInfoBox(itemImage, plugin, itemId,
                                    missingCount, itemName);
                            infoBoxManager.addInfoBox(infoBox);
                            currentInfoBoxes.put(itemId, infoBox);
                        }
                    }
                }
            }

            // Check if all items have been collected
            if (missingItemsWithCounts.isEmpty()) {
                plugin.setItemsCollected(true);
            } else {
                plugin.setItemsCollected(false);
            }

            // Render panel (for any other content if needed)
            return panelComponent.render(graphics);
        }

        // If items are collected, clear all InfoBoxes
        clearAllInfoBoxes();
        return null;
    }

    /** Clears missing-item InfoBoxes (e.g. after skipping or disabling the item checklist). */
    public void clearAllInfoBoxes() {
        if (infoBoxManager != null) {
            for (RequiredItemInfoBox infoBox : currentInfoBoxes.values()) {
                infoBoxManager.removeInfoBox(infoBox);
            }
        }
        currentInfoBoxes.clear();
    }

    /**
     * Gets the priority for sorting items in infoboxes.
     * Lower priority = appears first.
     * 
     * @param itemId The item ID to check
     * @return 0 for tools, 1 for regular teleport items, 2 for basalts, 3 for
     *         consumable supplies
     */
    private int getItemPriority(int itemId) {
        // Tools have lowest priority (appear first)
        if (isTool(itemId)) {
            return 0;
        }

        // Consumable supplies have highest priority (appear last)
        if (isConsumableSupply(itemId)) {
            return 3;
        }

        // Basalts have medium-high priority (appear last among teleport items)
        if (isBasalt(itemId)) {
            return 2;
        }

        // Regular teleport items have medium priority
        return 1;
    }

    /**
     * Determines if an item is a farming tool.
     * 
     * @param itemId The item ID to check
     * @return true if the item is a farming tool
     */
    private boolean isTool(int itemId) {
        return itemId == ItemID.SPADE ||
                itemId == ItemID.RAKE ||
                itemId == ItemID.DIBBER ||
                itemId == ItemID.FAIRY_ENCHANTED_SECATEURS ||
                isWateringCan(itemId);
    }

    /**
     * Determines if an item is a basalt teleport item.
     * 
     * @param itemId The item ID to check
     * @return true if the item is a basalt teleport item
     */
    private boolean isBasalt(int itemId) {
        return itemId == ItemID.STRONGHOLD_TELEPORT_BASALT ||
                itemId == ItemID.WEISS_TELEPORT_BASALT;
    }

    /**
     * Determines if an item is a consumable supply (seeds, compost) rather than a
     * teleport item.
     * Consumable supplies should appear after teleport items in the infobox
     * display.
     * 
     * @param itemId The item ID to check
     * @return true if the item is a consumable supply, false if it's a teleport
     *         item or tool
     */
    private boolean isConsumableSupply(int itemId) {
        // Check for seeds
        if (isHerbSeed(itemId) ||
                isTreeSapling(itemId) ||
                isFruitTreeSapling(itemId) ||
                isHopsSeed(itemId) ||
                isAllotmentSeed(itemId) ||
                isFlowerSeed(itemId)) {
            return true;
        }

        // Check for compost
        if (itemId == ItemID.BUCKET_COMPOST ||
                itemId == ItemID.BUCKET_SUPERCOMPOST ||
                itemId == ItemID.BUCKET_ULTRACOMPOST ||
                Constants.BOTTOMLESS_COMPOST_BUCKET_ITEM_IDS.contains(itemId)) {
            return true;
        }

        // Check for base seed IDs (used as placeholders)
        if (itemId == BASE_SEED_ID ||
                itemId == BASE_SAPLING_ID ||
                itemId == BASE_FRUIT_SAPLING_ID ||
                itemId == BASE_HOPS_SEED_ID ||
                itemId == BASE_ALLOTMENT_SEED_ID) {
            return true;
        }

        // Everything else (runes, teleport items, tools, etc.) is considered a teleport
        // item
        return false;
    }
}

package com.easyfarming;

import net.runelite.api.Client;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

import javax.inject.Inject;
import java.awt.Dimension;
import java.awt.Graphics2D;

/**
 * Overlay that displays text information in the top-left corner of the game screen.
 * Used to show current farming step instructions and debug information.
 * Only renders when the overlay is active.
 * Extends OverlayPanel for Runelite-consistent styling.
 *
 * The "Skip step" affordance for issue #98 lives in the plugin sidebar (EasyFarmingPanel /
 * OverviewPanel) rather than this in-game overlay, because RuneLite's PanelComponent children
 * are restricted to {@code LayoutableRenderableEntity} and cannot host a raw {@code JButton}.
 * Sidebar buttons are also easier to target with the mouse while playing.
 */
public class EasyFarmingOverlayInfoBox extends OverlayPanel {
    private final Client client;
    private final EasyFarmingPlugin plugin;

    private String text;
    private String debugText;

    @Inject
    public EasyFarmingOverlayInfoBox(Client client, EasyFarmingPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    public void setText(String text) {
        this.text = text;
    }

    public void setDebugText(String debugText) {
        this.debugText = debugText;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.isOverlayActive()) {
            return null;
        }

        getPanelComponent().getChildren().clear();

        if (text != null) {
            getPanelComponent().getChildren().add(LineComponent.builder().left(text).build());
        }

        if (debugText != null) {
            getPanelComponent().getChildren().add(LineComponent.builder().left(debugText).build());
        }

        return super.render(graphics);
    }
}

package com.easyfarming;

import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.swing.*;
import java.awt.*;

import com.easyfarming.customrun.CustomRun;
import com.easyfarming.ui.CustomRunDetailPanel;
import com.easyfarming.ui.OverviewPanel;

/**
 * Same UI style as the custom-run design: card layout with overview list and run detail.
 * Overview shows the 4 run types (Herb, Tree, Fruit Tree, Hops) and custom runs; detail shows locations and teleport dropdowns.
 */
public class EasyFarmingPanel extends PluginPanel {
    private static final String OVERVIEW_PANEL = "OVERVIEW";
    private static final String DETAIL_PANEL = "DETAIL";

    private final EasyFarmingPlugin plugin;
    private final OverlayManager overlayManager;
    private final FarmingTeleportOverlay farmingTeleportOverlay;
    private final net.runelite.client.game.ItemManager itemManager;

    private final JPanel cardContainer;
    private final CardLayout cardLayout;
    private OverviewPanel overviewPanel;
    private JPanel currentDetailPanel;

    public EasyFarmingPanel(EasyFarmingPlugin plugin,
                            OverlayManager overlayManager,
                            FarmingTeleportOverlay farmingTeleportOverlay,
                            net.runelite.client.game.ItemManager itemManager) {
        super(false);
        this.plugin = plugin;
        this.overlayManager = overlayManager;
        this.farmingTeleportOverlay = farmingTeleportOverlay;
        this.itemManager = itemManager;

        setLayout(new BorderLayout());
        cardLayout = new CardLayout();
        cardContainer = new JPanel(cardLayout);

        overviewPanel = new OverviewPanel(plugin, this);
        cardContainer.add(overviewPanel, OVERVIEW_PANEL);

        add(cardContainer, BorderLayout.CENTER);
    }

    public void showOverview() {
        if (overviewPanel != null) {
            overviewPanel.rebuildList();
        }
        cardLayout.show(cardContainer, OVERVIEW_PANEL);
        if (currentDetailPanel != null) {
            cardContainer.remove(currentDetailPanel);
            currentDetailPanel = null;
        }
    }

    /** Rebuild the overview list without switching cards (e.g. after rename/delete on a row). */
    public void refreshOverviewList() {
        if (overviewPanel != null) {
            overviewPanel.rebuildList();
        }
    }

    /** Called when a custom run starts so Skip / Start controls refresh on overview and detail. */
    public void onCustomRunStarted() {
        refreshOverviewList();
        if (currentDetailPanel instanceof CustomRunDetailPanel) {
            ((CustomRunDetailPanel) currentDetailPanel).refreshActiveRunControls();
        }
    }

    /** Called when the active custom run ends (e.g. last location completed). Refreshes overview and detail Start button. */
    public void onCustomRunEnded() {
        refreshOverviewList();
        if (currentDetailPanel instanceof CustomRunDetailPanel) {
            ((CustomRunDetailPanel) currentDetailPanel).refreshActiveRunControls();
        }
    }

    /** Refresh the active-location step-edit pencil when the live instruction changes. */
    public void refreshCurrentStepEditors() {
        if (currentDetailPanel instanceof CustomRunDetailPanel) {
            ((CustomRunDetailPanel) currentDetailPanel).refreshStepEditButtons();
        }
    }

    public void showRunDetail(CustomRun customRun) {
        if (currentDetailPanel != null) {
            cardContainer.remove(currentDetailPanel);
        }
        currentDetailPanel = new CustomRunDetailPanel(plugin, this, customRun, itemManager);
        cardContainer.add(currentDetailPanel, DETAIL_PANEL);
        cardLayout.show(cardContainer, DETAIL_PANEL);
    }

    /**
     * Starts the given custom run: overlay runs in custom mode with the run's locations and patch order.
     */
    public void startCustomRun(CustomRun customRun) {
        SwingUtilities.invokeLater(() -> {
            plugin.setOverlayActive(true);
            farmingTeleportOverlay.startCustomRun(customRun);
            EasyFarmingOverlay overlay = plugin.getEasyFarmingOverlay();
            if (overlay != null) {
                overlayManager.add(overlay);
            }
            overlayManager.add(farmingTeleportOverlay);
            onCustomRunStarted();
        });
    }
}

package com.easyfarming;

import com.easyfarming.customrun.CustomRunStorage;
import com.easyfarming.customrun.CurrentStepInstruction;
import com.easyfarming.customrun.LocationCatalog;
import com.easyfarming.customrun.NavigationTextOverrides;
import com.easyfarming.core.Teleport;
import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;

import lombok.Getter;
import lombok.Setter;
import net.runelite.api.*;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;

@PluginDescriptor(
		name = "Easy Farming",
		description = "Show item requirements and highlights for farming runs."
)

public class EasyFarmingPlugin extends Plugin
{
	@Inject
	private ItemManager itemManager;
	@Inject
	private ConfigManager configManager;
	@Inject
	private Gson gson;
	@Getter
    @Inject
	private Client client;

	private LocationCatalog locationCatalog;
	private CustomRunStorage customRunStorage;
	private NavigationTextOverrides navigationTextOverrides;

	public LocationCatalog getLocationCatalog() {
		if (locationCatalog == null) {
			locationCatalog = new LocationCatalog(this);
		}
		return locationCatalog;
	}

	public CustomRunStorage getCustomRunStorage() {
		if (customRunStorage == null) {
			customRunStorage = new CustomRunStorage(configManager, gson);
		}
		return customRunStorage;
	}

	public NavigationTextOverrides getNavigationTextOverrides() {
		if (navigationTextOverrides == null) {
			navigationTextOverrides = new NavigationTextOverrides(configManager, gson);
		}
		return navigationTextOverrides;
	}

	@Getter
	private CurrentStepInstruction currentStepInstruction;
	private String lastNotifiedStepIdentity = "";

	/**
	 * Shows navigation instruction text (with overrides) and records it as the editable current step.
	 */
	public void setNavigationInstruction(String locationName, Teleport teleport) {
		NavigationTextOverrides overrides = getNavigationTextOverrides();
		String defaultText = teleport != null && teleport.getDescription() != null ? teleport.getDescription() : "";
		String resolved = overrides.resolve(locationName, teleport);
		if (farmingHelperOverlayInfoBox != null) {
			farmingHelperOverlayInfoBox.setText(resolved);
		}
		currentStepInstruction = CurrentStepInstruction.navigation(
				locationName,
				teleport != null ? teleport.getEnumOption() : null,
				defaultText);
		maybeNotifyCurrentStepUi();
	}

	public void clearCurrentStepInstruction() {
		currentStepInstruction = null;
		lastNotifiedStepIdentity = "";
		if (panel != null) {
			SwingUtilities.invokeLater(panel::refreshCurrentStepEditors);
		}
	}

	private void maybeNotifyCurrentStepUi() {
		String identity = currentStepInstruction != null ? currentStepInstruction.identity() : "";
		if (identity.equals(lastNotifiedStepIdentity)) {
			return;
		}
		lastNotifiedStepIdentity = identity;
		if (panel != null) {
			SwingUtilities.invokeLater(panel::refreshCurrentStepEditors);
		}
	}

	public void runOnClientThread(Runnable task) {
		clientThread.invokeLater(task);
	}

	@Getter
    @Setter
    private boolean isTeleportOverlayActive = false;

    @Inject
	private EasyFarmingOverlayInfoBox farmingHelperOverlayInfoBox;
	public EasyFarmingOverlayInfoBox getEasyFarmingOverlayInfoBox()
	{
		return farmingHelperOverlayInfoBox;
	}

	@Getter
    private String lastMessage = "";
    @Subscribe
    public void onChatMessage(ChatMessage event) {
        String message = event.getMessage();

        // Store last message for other purposes (compost detection, etc.)
        if (event.getType() == ChatMessageType.GAMEMESSAGE) {
            lastMessage = message;
        }
        else if (event.getType() == ChatMessageType.SPAM) {
            lastMessage = message;
        }
    }

    public boolean checkMessage(String targetMessage, String lastMessage) {
		return lastMessage.trim().equalsIgnoreCase(targetMessage.trim());
	}

	/**
	 * Clears the last game message used for compost/protection detection. Call when advancing to the
	 * next patch at the same location so a compost line from the previous patch is not applied to the next.
	 */
	public void clearLastMessage() {
		lastMessage = "";
	}

	/**
	 * Skip the current step of an active custom run (item checklist, navigation, or farming).
	 * Called by the "Skip current step" button. No-op when no custom run is active.
	 * Clears {@code lastMessage} so a chat line from a skipped step cannot poison the next
	 * step's compost detection (see {@link com.easyfarming.overlays.utils.PatchStateChecker}).
	 */
	public void skipCurrentStep() {
		if (farmingTeleportOverlay == null || !farmingTeleportOverlay.isCustomRunMode()) {
			return;
		}
		clearLastMessage();
		farmingTeleportOverlay.skipCurrentStep();
	}

	/**
	 * Marks the item-gathering phase complete and enables teleport/navigation overlays.
	 * Used when the run has "Skip item checklist" enabled, or when the user skips that step.
	 */
	public void completeItemGatheringPhase() {
		itemsCollected = true;
		isTeleportOverlayActive = true;
		if (farmingHelperOverlay != null) {
			farmingHelperOverlay.clearAllInfoBoxes();
		}
	}

	@Inject
	private EventBus eventBus;

	@Inject
	private ClientThread clientThread;


	@Getter
    @Inject
	private FarmingTeleportOverlay farmingTeleportOverlay;
	@Inject
	private FarmingTeleportSceneOverlay farmingTeleportSceneOverlay;

	private EasyFarmingPanel farmingHelperPanel;
	public EasyFarmingPanel panel;
	private NavigationButton navButton;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private EasyFarmingConfig config;

	public EasyFarmingConfig getConfig() {
		return config;
	}

	/** Custom run tool inclusion: set when starting a custom run from the detail panel. */
	private boolean customRunIncludeSecateurs = true;
	private boolean customRunIncludeDibber = true;
	private boolean customRunIncludeRake = true;

	public void setCustomRunToolInclusion(boolean secateurs, boolean dibber, boolean rake) {
		this.customRunIncludeSecateurs = secateurs;
		this.customRunIncludeDibber = dibber;
		this.customRunIncludeRake = rake;
	}

	public boolean getCustomRunIncludeSecateurs() { return customRunIncludeSecateurs; }
	public boolean getCustomRunIncludeDibber() { return customRunIncludeDibber; }
	public boolean getCustomRunIncludeRake() { return customRunIncludeRake; }

	@Inject
	public OverlayManager overlayManager;
	@Inject
	public InfoBoxManager infoBoxManager;

	@Getter
    @Setter
    private boolean isOverlayActive = true;

	@Inject
	private EasyFarmingOverlay farmingHelperOverlay;

	public EasyFarmingOverlay getEasyFarmingOverlay()
	{
		return farmingHelperOverlay;
	}

	@Setter
    private boolean itemsCollected = false;
	public boolean areItemsCollected() {
		return itemsCollected;
	}

	@Provides
	EasyFarmingConfig getConfig(ConfigManager configManager)
	{
		return configManager.getConfig(EasyFarmingConfig.class);
	}

	@Provides
	com.easyfarming.overlays.utils.ColorProvider provideColorProvider(EasyFarmingConfig config)
	{
		return new com.easyfarming.overlays.utils.ColorProvider(config);
	}

	@Provides
	EasyFarmingOverlay provideEasyFarmingOverlay(Client client, EasyFarmingPlugin plugin, ItemManager itemManager, InfoBoxManager infoBoxManager)
	{
		return new EasyFarmingOverlay(client, plugin, itemManager, infoBoxManager);
	}

    public void addTextToInfoBox(String text) {
		String defaultText = text != null ? text : "";
		String resolved = getNavigationTextOverrides().resolveStep(defaultText);
		if (farmingHelperOverlayInfoBox != null) {
			farmingHelperOverlayInfoBox.setText(resolved);
		}
		String locationName = null;
		if (farmingTeleportOverlay != null && farmingTeleportOverlay.isCustomRunMode()) {
			locationName = farmingTeleportOverlay.getActiveLocationName();
		}
		currentStepInstruction = CurrentStepInstruction.farming(locationName, defaultText);
		maybeNotifyCurrentStepUi();
	}

    public void addDebugTextToInfoBox(String debugText) {
		farmingHelperOverlayInfoBox.setDebugText(debugText);
	}

	@Override
	protected void startUp()
	{
		farmingHelperOverlay = new EasyFarmingOverlay(client, this, itemManager, infoBoxManager);

		panel = new EasyFarmingPanel(this, overlayManager, farmingTeleportOverlay, itemManager);
		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/icon.png");

		navButton = NavigationButton.builder()
				.tooltip("Easy Farming")
				.icon(icon)
				.priority(6)
				.panel(panel)
				.build();
		clientToolbar.addNavigation(navButton);

		overlayManager.add(farmingHelperOverlay);
		overlayManager.add(farmingTeleportSceneOverlay);
		overlayManager.add(farmingTeleportOverlay);
		overlayManager.add(farmingHelperOverlayInfoBox);

		// set overlay to inactive
		isOverlayActive = false;
		eventBus.register(this);
	}

	@Override
	protected void shutDown()
	{
		if (navButton != null) {
			clientToolbar.removeNavigation(navButton);
		}

		overlayManager.remove(farmingHelperOverlay);
		overlayManager.remove(farmingTeleportSceneOverlay);
		overlayManager.remove(farmingTeleportOverlay);
		overlayManager.remove(farmingHelperOverlayInfoBox);

		eventBus.unregister(this);
	}
}

package com.easyfarming;

import java.awt.*;
import javax.inject.Inject;

import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import com.easyfarming.core.Teleport;
import com.easyfarming.core.Location;
import com.easyfarming.customrun.LocationCatalog;
import com.easyfarming.customrun.PatchTypes;
import com.easyfarming.customrun.CustomRun;
import com.easyfarming.customrun.RunLocation;
import com.easyfarming.overlays.handlers.NavigationHandler;
import com.easyfarming.overlays.handlers.FarmingStepHandler;

import javax.swing.SwingUtilities;
import java.util.ArrayList;
import java.util.List;

public class FarmingTeleportOverlay extends Overlay {
    private final Client client;
    private final EasyFarmingPlugin plugin;
    private final EasyFarmingConfig config;
    private final AreaCheck areaCheck;

    @Inject
    private EasyFarmingOverlay farmingHelperOverlay;
    @Inject
    private EasyFarmingOverlayInfoBox farmingHelperOverlayInfoBox;
    @Inject
    private NavigationHandler navigationHandler;
    @Inject
    private FarmingStepHandler farmingStepHandler;
    @Inject
    private FarmingTeleportSceneOverlay farmingTeleportSceneOverlay;

    // Custom run state
    private boolean customRunMode = false;
    private List<RunLocation> customRunLocations = new ArrayList<>();
    /** Name of the custom run currently active (so UI can show Stop on the correct run). */
    private String activeCustomRunName = null;

    public boolean isCustomRunMode() {
        return customRunMode;
    }

    public List<RunLocation> getCustomRunLocations() {
        return customRunLocations;
    }

    public String getActiveCustomRunName() {
        return activeCustomRunName;
    }

    /** Name of the location currently being run, or null if none. */
    public String getActiveLocationName() {
        if (!customRunMode || customRunLocations.isEmpty() || currentLocationIndex >= customRunLocations.size()) {
            return null;
        }
        RunLocation rl = customRunLocations.get(currentLocationIndex);
        return rl != null ? rl.getLocationName() : null;
    }

    private int currentPatchTypeIndex = 0;

    // Location tracking
    private int currentLocationIndex = 0;

    // Farming state
    private boolean startSubCases = false;
    private boolean isAtDestination = false;
    private boolean farmLimps = false;

    @Inject
    public FarmingTeleportOverlay(EasyFarmingPlugin plugin, Client client, AreaCheck areaCheck, 
                                   EasyFarmingConfig config) {
        this.areaCheck = areaCheck;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        this.plugin = plugin;
        this.client = client;
        this.config = config;
    }

    /**
     * Gets patch point for a location and patch type (used in custom run mode).
     */
    public WorldPoint getPatchPointForLocationAndType(String locationName, String patchType) {
        if (patchType == null) return null;
        switch (patchType) {
            case PatchTypes.HERB:
            case PatchTypes.FLOWER:
            case PatchTypes.ALLOTMENT:
                return getHerbPatchPoint(locationName);
            case PatchTypes.TREE:
                return getTreePatchPoint(locationName);
            case PatchTypes.FRUIT_TREE:
                return getFruitTreePatchPoint(locationName);
            case PatchTypes.HOPS:
                return getHopsPatchPoint(locationName);
            default:
                return null;
        }
    }

    /**
     * Gets herb patch coordinates for a location.
     * TODO: Move these to Location objects or a constants class
     */
    private WorldPoint getHerbPatchPoint(String locationName) {
        switch (locationName) {
            case "Ardougne": return new WorldPoint(2670, 3374, 0);
            case "Catherby": return new WorldPoint(2813, 3463, 0);
            case "Falador": return new WorldPoint(3058, 3307, 0);
            case "Farming Guild": return new WorldPoint(1238, 3726, 0);
            case "Harmony Island": return new WorldPoint(3789, 2837, 0);
            case "Kourend": return new WorldPoint(1738, 3550, 0);
            case "Morytania": return new WorldPoint(3601, 3525, 0);
            case "Troll Stronghold": return new WorldPoint(2824, 3696, 0);
            case "Weiss": return new WorldPoint(2847, 3931, 0);
            case "Civitas illa Fortis": return new WorldPoint(1586, 3099, 0);
            default: return null;
        }
    }

    private WorldPoint getTreePatchPoint(String locationName) {
        switch (locationName) {
            case "Falador": return new WorldPoint(3000, 3373, 0);
            case "Farming Guild": return new WorldPoint(1232, 3736, 0);
            case "Gnome Stronghold": return new WorldPoint(2436, 3415, 0);
            case "Lumbridge": return new WorldPoint(3193, 3231, 0);
            case "Taverley": return new WorldPoint(2936, 3438, 0);
            case "Varrock": return new WorldPoint(3229, 3459, 0);
            case "Nemus Retreat": return new WorldPoint(1366, 3321, 0);
            default: return null;
        }
    }

    private WorldPoint getFruitTreePatchPoint(String locationName) {
        switch (locationName) {
            case "Brimhaven": return new WorldPoint(2764, 3212, 0);
            case "Catherby": return new WorldPoint(2860, 3433, 0);
            case "Farming Guild": return new WorldPoint(1243, 3759, 0);
            case "Gnome Stronghold": return new WorldPoint(2475, 3446, 0);
            case "Lletya": return new WorldPoint(2346, 3162, 0);
            case "Tree Gnome Village": return new WorldPoint(2490, 3180, 0);
            case "Kastori": return new WorldPoint(1350, 3057, 0);
            default: return null;
        }
    }

    private WorldPoint getHopsPatchPoint(String locationName) {
        switch (locationName) {
            case "Aldarin": return new WorldPoint(1365, 2939, 0);
            case "Entrana": return new WorldPoint(2811, 3337, 0);
            case "Lumbridge": return new WorldPoint(3229, 3315, 0);
            case "Seers Village": return new WorldPoint(2667, 3526, 0);
            case "Yanille": return new WorldPoint(2576, 3105, 0);
            default: return null;
        }
    }

    /**
     * Returns the current Location (with teleport override set) and patch type when in custom run mode; otherwise null.
     */
    private Location getCurrentLocationForCustomRun() {
        if (!customRunMode || customRunLocations.isEmpty() || currentLocationIndex >= customRunLocations.size()) {
            return null;
        }
        RunLocation rl = customRunLocations.get(currentLocationIndex);
        List<String> patchTypes = rl.getPatchTypes();
        if (patchTypes == null || patchTypes.isEmpty() || currentPatchTypeIndex >= patchTypes.size()) {
            return null;
        }
        String patchType = patchTypes.get(currentPatchTypeIndex);
        LocationCatalog catalog = plugin.getLocationCatalog();
        Location loc = catalog.getLocationForPatch(rl.getLocationName(), patchType);
        if (loc != null && rl.getTeleportOption() != null) {
            loc.setOverrideTeleportEnumOption(rl.getTeleportOption());
        }
        return loc;
    }

    private String getCurrentPatchTypeForCustomRun() {
        if (!customRunMode || customRunLocations.isEmpty() || currentLocationIndex >= customRunLocations.size()) {
            return null;
        }
        RunLocation rl = customRunLocations.get(currentLocationIndex);
        List<String> patchTypes = rl.getPatchTypes();
        if (patchTypes == null || currentPatchTypeIndex >= patchTypes.size()) return null;
        return patchTypes.get(currentPatchTypeIndex);
    }

    /**
     * Manages hint arrows for navigation.
     */
    private void updateHintArrow(Location location) {
        String patchType = getCurrentPatchTypeForCustomRun();
        WorldPoint patchPoint = location != null && patchType != null
                ? getPatchPointForLocationAndType(location.getName(), patchType)
                : null;
        if (patchPoint == null) {
            return;
        }

        if (client.getLocalPlayer() == null) {
            return;
        }

        int currentRegionId = client.getLocalPlayer().getWorldLocation().getRegionID();
        // Morytania: slightly larger radius so navigation hint clears before farming steps
        // (aligns with FarmingStepHandler PATCH_HINT_ARROW_RANGE_TILES).
        int clearDistance = "Morytania".equals(location.getName()) ? 15 : 5;

        // Special handling for Brimhaven
        boolean isBrimhavenFruitTree = customRunMode && PatchTypes.FRUIT_TREE.equals(getCurrentPatchTypeForCustomRun()) && "Brimhaven".equals(location.getName());
        if (isBrimhavenFruitTree) {
            if (currentRegionId == 10547) {
                boolean nearBrimhavenPatch = areaCheck.isPlayerWithinArea(patchPoint, 20);
                if (!nearBrimhavenPatch) {
                    WorldPoint captainBarnabyLocation = new WorldPoint(2675, 3265, 0);
                    client.setHintArrow(captainBarnabyLocation);
                    return;
                }
            }
        }

        // Special handling for Entrana
        boolean isEntranaHops = customRunMode && PatchTypes.HOPS.equals(getCurrentPatchTypeForCustomRun()) && "Entrana".equals(location.getName());
        if (isEntranaHops) {
            boolean nearEntranaPatch = areaCheck.isPlayerWithinArea(patchPoint, 20);
            if (!nearEntranaPatch) {
                WorldPoint entranaMonkLocation = new WorldPoint(3042, 3235, 0);
                client.setHintArrow(entranaMonkLocation);
                return;
            }
        }

        // Normal hint arrow handling
        boolean nearPatch = areaCheck.isPlayerWithinArea(patchPoint, clearDistance);
        if (nearPatch) {
            client.clearHintArrow();
        } else if (!isAtDestination) {
            client.setHintArrow(patchPoint);
        }
    }

    /**
     * Handles navigation to the current location.
     */
    private void navigateToCurrentLocation(Graphics2D graphics) {
        Location location = getCurrentLocationForCustomRun();
        if (location == null) {
            moveToNextLocation();
            return;
        }
        updateHintArrow(location);
        navigationHandler.gettingToLocation(graphics, location, getCurrentPatchTypeForCustomRun());
        if (navigationHandler.isAtDestination) {
            isAtDestination = true;
            startSubCases = true;
            if (location.getFarmLimps()) farmLimps = true;
            // Navigation hint points at the patch tile until "near" clears it; destination can be
            // reached while still outside that radius, after which updateHintArrow no longer runs.
            farmingStepHandler.clearHintArrow();
        }
    }

    /**
     * Handles farming steps at the current location.
     */
    private void handleFarmingSteps(Graphics2D graphics) {
        if (!startSubCases) {
            return;
        }
        handleCustomRunSteps(graphics);
    }

    private void handleCustomRunSteps(Graphics2D graphics) {
        Location location = getCurrentLocationForCustomRun();
        String patchType = getCurrentPatchTypeForCustomRun();
        if (location == null || patchType == null) {
            moveToNextLocation();
            return;
        }
        Teleport teleport = location.getSelectedTeleport();
        if (teleport == null) {
            moveToNextLocation();
            return;
        }
        switch (patchType) {
            case PatchTypes.HERB:
                farmingStepHandler.herbSteps(graphics, teleport);
                if (farmingStepHandler.herbPatchDone) {
                    farmingStepHandler.herbPatchDone = false;
                    moveToNextPatchOrLocation();
                }
                break;
            case PatchTypes.FLOWER:
                farmingStepHandler.flowerSteps(graphics, farmLimps);
                if (farmingStepHandler.flowerPatchDone) {
                    farmingStepHandler.flowerPatchDone = false;
                    moveToNextPatchOrLocation();
                }
                break;
            case PatchTypes.ALLOTMENT:
                farmingStepHandler.allotmentSteps(graphics, teleport);
                if (farmingStepHandler.allotmentPatchDone) {
                    farmingStepHandler.allotmentPatchDone = false;
                    moveToNextPatchOrLocation();
                }
                break;
            case PatchTypes.TREE:
                farmingStepHandler.treeSteps(graphics, teleport);
                if (farmingStepHandler.treePatchDone) {
                    farmingStepHandler.treePatchDone = false;
                    moveToNextPatchOrLocation();
                }
                break;
            case PatchTypes.FRUIT_TREE:
                farmingStepHandler.fruitTreeSteps(graphics, teleport);
                if (farmingStepHandler.fruitTreePatchDone) {
                    farmingStepHandler.fruitTreePatchDone = false;
                    moveToNextPatchOrLocation();
                }
                break;
            case PatchTypes.HOPS:
                farmingStepHandler.hopsSteps(graphics, teleport);
                if (farmingStepHandler.hopsPatchDone) {
                    farmingStepHandler.hopsPatchDone = false;
                    moveToNextPatchOrLocation();
                }
                break;
            default:
                moveToNextPatchOrLocation();
        }
    }

    private void moveToNextPatchOrLocation() {
        if (!customRunMode || customRunLocations.isEmpty()) {
            moveToNextLocation();
            return;
        }
        RunLocation rl = customRunLocations.get(currentLocationIndex);
        List<String> patchTypes = rl.getPatchTypes();
        if (patchTypes != null && currentPatchTypeIndex + 1 < patchTypes.size()) {
            currentPatchTypeIndex++;
            farmingStepHandler.herbPatchDone = false;
            farmingStepHandler.flowerPatchDone = false;
            farmingStepHandler.allotmentPatchDone = false;
            farmingStepHandler.treePatchDone = false;
            farmingStepHandler.fruitTreePatchDone = false;
            farmingStepHandler.hopsPatchDone = false;
            farmingStepHandler.resetCompostStates();
            plugin.clearLastMessage();
            return;
        }
        moveToNextLocation();
    }

    /**
     * Moves to the next location in the run.
     */
    private void moveToNextLocation() {
        startSubCases = false;
        isAtDestination = false;
        currentLocationIndex++;
        currentPatchTypeIndex = 0;
        farmLimps = false;

        // Reset farming step handler states
        farmingStepHandler.herbPatchDone = false;
        farmingStepHandler.flowerPatchDone = false;
        farmingStepHandler.allotmentPatchDone = false;
        farmingStepHandler.treePatchDone = false;
        farmingStepHandler.fruitTreePatchDone = false;
        farmingStepHandler.hopsPatchDone = false;

        // Reset persistent compost states
        farmingStepHandler.resetCompostStates();
        plugin.clearLastMessage();

        // Reset navigation handler state for the new location
        navigationHandler.currentTeleportCase = 1;
        navigationHandler.isAtDestination = false;

        if (currentLocationIndex >= customRunLocations.size()) {
            removeOverlay();
        }
    }

    /**
     * Skip the current step of the active custom run. No-op when not in a custom run.
     * <ul>
     *   <li>During item gathering: complete the checklist (including stuck seed-box check)
     *       and enable teleport / navigation.</li>
     *   <li>During navigation: treat the player as arrived so farming instructions for the
     *       current patch begin on the next render (does not mark the patch done).</li>
     *   <li>During farming: mark only the active patch type done so the next render advances
     *       via {@link #moveToNextPatchOrLocation()}.</li>
     * </ul>
     */
    public void skipCurrentStep() {
        if (!customRunMode || farmingStepHandler == null) {
            return;
        }
        if (!plugin.areItemsCollected()) {
            plugin.completeItemGatheringPhase();
            return;
        }
        if (!isAtDestination) {
            Location location = getCurrentLocationForCustomRun();
            isAtDestination = true;
            startSubCases = true;
            navigationHandler.isAtDestination = true;
            if (location != null && location.getFarmLimps()) {
                farmLimps = true;
            }
            farmingStepHandler.clearHintArrow();
            return;
        }
        farmingStepHandler.forceAdvancePatchType(getCurrentPatchTypeForCustomRun());
    }

    public void removeOverlay() {
        plugin.overlayManager.remove(farmingHelperOverlay);
        plugin.overlayManager.remove(this);
        plugin.overlayManager.remove(farmingHelperOverlayInfoBox);

        plugin.setOverlayActive(false);
        plugin.setTeleportOverlayActive(false);

        customRunMode = false;
        customRunLocations.clear();
        activeCustomRunName = null;
        currentPatchTypeIndex = 0;
        currentLocationIndex = 0;
        startSubCases = false;
        isAtDestination = false;
        farmLimps = false;

        farmingStepHandler.herbPatchDone = false;
        farmingStepHandler.flowerPatchDone = false;
        farmingStepHandler.allotmentPatchDone = false;
        farmingStepHandler.treePatchDone = false;
        farmingStepHandler.fruitTreePatchDone = false;
        farmingStepHandler.hopsPatchDone = false;
        farmingStepHandler.clearHintArrow();

        // Reset persistent compost states
        farmingStepHandler.resetCompostStates();
        plugin.clearLastMessage();

        navigationHandler.currentTeleportCase = 1;
        navigationHandler.isAtDestination = false;

        plugin.setItemsCollected(false);
        plugin.clearCurrentStepInstruction();

        SwingUtilities.invokeLater(() -> {
            if (plugin.panel != null) {
                plugin.panel.onCustomRunEnded();
            }
        });
    }

    public void startCustomRun(CustomRun run) {
        if (run == null || run.getLocations() == null) {
            return;
        }
        // Use run's config/saved state for required items (no fallbacks)
        plugin.setCustomRunToolInclusion(
            run.isIncludeSecateurs(),
            run.isIncludeDibber(),
            run.isIncludeRake());
        farmingStepHandler.herbPatchDone = false;
        farmingStepHandler.flowerPatchDone = false;
        farmingStepHandler.allotmentPatchDone = false;
        farmingStepHandler.treePatchDone = false;
        farmingStepHandler.fruitTreePatchDone = false;
        farmingStepHandler.hopsPatchDone = false;
        farmingStepHandler.clearHintArrow();
        farmingStepHandler.resetCompostStates();
        plugin.clearLastMessage();
        customRunMode = true;
        activeCustomRunName = run.getName();
        customRunLocations = new ArrayList<>(run.getLocations());
        currentLocationIndex = 0;
        currentPatchTypeIndex = 0;
        startSubCases = false;
        isAtDestination = false;
        farmLimps = false;
        navigationHandler.currentTeleportCase = 1;
        navigationHandler.isAtDestination = false;
        if (run.isSkipItemGathering()) {
            plugin.completeItemGatheringPhase();
        } else {
            plugin.setItemsCollected(false);
            plugin.setTeleportOverlayActive(false);
        }
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.isTeleportOverlayActive()) {
            return null;
        }

        // Guard against rendering before player is fully loaded
        if (client.getLocalPlayer() == null) {
            return null;
        }

        if (customRunLocations.isEmpty()) {
            removeOverlay();
            return null;
        }

        farmingTeleportSceneOverlay.clearSpiritTreeHighlight();

        if (isAtDestination) {
            handleFarmingSteps(graphics);
        } else {
            navigateToCurrentLocation(graphics);
        }

        return null;
    }
}

package com.easyfarming;

import java.awt.*;
import javax.inject.Inject;

import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import com.easyfarming.overlays.highlighting.GameObjectHighlighter;
import com.easyfarming.utils.Constants;

/**
 * Draws teleport-related scene highlights (e.g. Spirit Tree object) at ABOVE_SCENE
 * so they appear correctly on the game scene/map instead of above widgets.
 */
public class FarmingTeleportSceneOverlay extends Overlay {
    private final GameObjectHighlighter gameObjectHighlighter;

    /** Set by NavigationHandler when spirit tree object should be highlighted next frame. */
    private volatile Color spiritTreeHighlightColor = null;

    @Inject
    public FarmingTeleportSceneOverlay(GameObjectHighlighter gameObjectHighlighter) {
        this.gameObjectHighlighter = gameObjectHighlighter;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    /**
     * Request spirit tree game objects to be highlighted (above scene).
     * Called from NavigationHandler/TeleportHighlighter when the Spirit Tree interface is not open.
     */
    public void requestSpiritTreeHighlight(Color color) {
        this.spiritTreeHighlightColor = color;
    }

    /**
     * Clear spirit tree highlight request. Call at start of teleport overlay render
     * so we stop drawing when no longer on the spirit tree step.
     */
    public void clearSpiritTreeHighlight() {
        this.spiritTreeHighlightColor = null;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (spiritTreeHighlightColor == null) {
            return null;
        }
        Color color = spiritTreeHighlightColor;
        gameObjectHighlighter.renderGameObjectHighlights(graphics, Constants.SPIRIT_TREE_IDS, color);
        return null;
    }
}

package com.easyfarming;

import net.runelite.api.Client;

/**
 * Flower patch state detection using range-based varbit value checks.
 * 
 * This implementation uses the exact varbit ranges from RuneLite's PatchImplementation
 * (FLOWER section, lines 718-990) to determine crop state without hardcoding all varbit values.
 * 
 * Varbit ID: 4773 (FARMING_TRANSMIT_C) - used for all flower patches
 */
public class FlowerPatchChecker {

    /**
     * Checks the state of a flower patch based on varbit value ranges.
     * 
     * This method uses the exact varbit ranges from RuneLite's PatchImplementation
     * to determine crop state without hardcoding all varbit values.
     * 
     * @param client The RuneLite client instance
     * @param varbitIndex The varbit ID for the patch
     * @return The current state of the patch
     */
    public static PlantState checkFlowerPatch(Client client, int varbitIndex) {
        int value = client.getVarbitValue(varbitIndex);

        // Check for empty patch ready to plant (value 3 = fully raked)
        if (value == 3) {
            return PlantState.PLANT;
        }

        // Check harvestable first (before other states, as harvest values might overlap)
        // Marigold[Pick,Inspect,Guide] 12
        if (value == 12) {
            return PlantState.HARVESTABLE;
        }
        // Rosemary[Pick,Inspect,Guide] 17
        if (value == 17) {
            return PlantState.HARVESTABLE;
        }
        // Nasturtium[Pick,Inspect,Guide] 22
        if (value == 22) {
            return PlantState.HARVESTABLE;
        }
        // Woad plant[Pick,Inspect,Guide] 27
        if (value == 27) {
            return PlantState.HARVESTABLE;
        }
        // Limpwurt plant[Pick,Inspect,Guide] 32
        if (value == 32) {
            return PlantState.HARVESTABLE;
        }
        // White lily[Pick,Inspect,Guide] 41
        if (value == 41) {
            return PlantState.HARVESTABLE;
        }

        // Check dead before diseased, as dead is a more specific state
        // Dead marigold[Clear,Inspect,Guide] 201-204
        if (value >= 201 && value <= 204) {
            return PlantState.DEAD;
        }
        // Dead rosemary[Clear,Inspect,Guide] 206-209
        if (value >= 206 && value <= 209) {
            return PlantState.DEAD;
        }
        // Dead nasturtium[Clear,Inspect,Guide] 211-214
        if (value >= 211 && value <= 214) {
            return PlantState.DEAD;
        }
        // Dead woad plant[Clear,Inspect,Guide] 216-219
        if (value >= 216 && value <= 219) {
            return PlantState.DEAD;
        }
        // Dead limpwurt plant[Clear,Inspect,Guide] 221-224
        if (value >= 221 && value <= 224) {
            return PlantState.DEAD;
        }
        // Dead White lily[Clear,Inspect,Guide] 230-233
        if (value >= 230 && value <= 233) {
            return PlantState.DEAD;
        }

        // Check diseased state
        // Diseased marigold[Cure,Inspect,Guide] 137-139
        if (value >= 137 && value <= 139) {
            return PlantState.DISEASED;
        }
        // Diseased rosemary[Cure,Inspect,Guide] 142-144
        if (value >= 142 && value <= 144) {
            return PlantState.DISEASED;
        }
        // Diseased nasturtium[Cure,Inspect,Guide] 147-149
        if (value >= 147 && value <= 149) {
            return PlantState.DISEASED;
        }
        // Diseased woad plant[Cure,Inspect,Guide] 152-154
        if (value >= 152 && value <= 154) {
            return PlantState.DISEASED;
        }
        // Diseased limpwurt plant[Cure,Inspect,Guide] 157-159
        if (value >= 157 && value <= 159) {
            return PlantState.DISEASED;
        }
        // Diseased White lily[Cure,Inspect,Guide] 166-168
        if (value >= 166 && value <= 168) {
            return PlantState.DISEASED;
        }

        // Check weeds (all weed states)
        // Flower Patch[Rake,Inspect,Guide] 0-2
        if (value >= 0 && value <= 2) {
            return PlantState.WEEDS;
        }
        // Flower Patch[Rake,Inspect,Guide] 4-7
        if (value >= 4 && value <= 7) {
            return PlantState.WEEDS;
        }
        // Flower Patch[Rake,Inspect,Guide] 42-71
        if (value >= 42 && value <= 71) {
            return PlantState.WEEDS;
        }
        // Flower Patch[Rake,Inspect,Guide] 76
        if (value == 76) {
            return PlantState.WEEDS;
        }
        // Flower Patch[Rake,Inspect,Guide] 81
        if (value == 81) {
            return PlantState.WEEDS;
        }
        // Flower Patch[Rake,Inspect,Guide] 86
        if (value == 86) {
            return PlantState.WEEDS;
        }
        // Flower Patch[Rake,Inspect,Guide] 91
        if (value == 91) {
            return PlantState.WEEDS;
        }
        // Flower Patch[Rake,Inspect,Guide] 96-100
        if (value >= 96 && value <= 100) {
            return PlantState.WEEDS;
        }
        // Flower Patch[Rake,Inspect,Guide] 105-136
        if (value >= 105 && value <= 136) {
            return PlantState.WEEDS;
        }
