        addTeleports(aldarinHops.getName(), aldarinHops);
        addPatchTypes(aldarinHops.getName(), singletonList(PatchTypes.HOPS));

        allLocationNames.addAll(seenNames);
    }

    private void putLocationForPatch(String locationName, String patchType, Location loc) {
        locationByPatch.computeIfAbsent(locationName, k -> new HashMap<>()).put(patchType, loc);
    }

    private void addTeleports(String locationName, Location loc) {
        List<String> opts = loc.getTeleportOptions() == null
                ? Collections.emptyList()
                : loc.getTeleportOptions().stream()
                        .map(Teleport::getEnumOption)
                        .collect(Collectors.toList());
        teleportOptionsByLocation
                .computeIfAbsent(locationName, k -> new ArrayList<>())
                .addAll(opts);
    }

    private void addPatchTypes(String locationName, List<String> types) {
        List<String> existing = patchTypesByLocation.computeIfAbsent(locationName, k -> new ArrayList<>());
        for (String t : types) {
            if (!existing.contains(t)) {
                existing.add(t);
            }
        }
    }

    public Location getLocationForPatch(String locationName, String patchType) {
        Map<String, Location> byType = locationByPatch.get(locationName);
        return byType != null ? byType.get(patchType) : null;
    }

    /** Returns merged teleport enum option strings for the location (may contain duplicates; caller can dedupe). */
    public List<String> getTeleportOptionsForLocation(String locationName) {
        List<String> opts = teleportOptionsByLocation.get(locationName);
        if (opts == null) return Collections.emptyList();
        return new ArrayList<>(new LinkedHashSet<>(opts));
    }

    public List<String> getPatchTypesAtLocation(String locationName) {
        List<String> types = patchTypesByLocation.get(locationName);
        return types != null ? new ArrayList<>(types) : Collections.emptyList();
    }

    /**
     * Returns the config default teleport enum option for a location when creating a new custom run.
     * Uses the config default from each patch type at this location; for a single teleport per location
     * we use the first patch type's config default (herb/allotment before tree/fruit tree/hops).
     * If the config default is not in the allowed teleport list, falls back to the first allowed option.
     */
    public String getDefaultTeleportOptionForNewRun(String locationName) {
        List<String> patchTypes = getPatchTypesAtLocation(locationName);
        if (patchTypes.isEmpty()) return null;
        Location location = getLocationForPatch(locationName, patchTypes.get(0));
        if (location == null) return null;
        Teleport selected = location.getSelectedTeleport();
        String configDefault = (selected != null && selected.getEnumOption() != null) ? selected.getEnumOption() : null;
        List<String> allowed = getTeleportOptionsForLocation(locationName);
        if (configDefault != null && allowed.stream().anyMatch(opt -> configDefault.equalsIgnoreCase(opt))) {
            return configDefault;
        }
        return allowed.isEmpty() ? null : allowed.get(0);
    }

    public List<String> getAllLocationNames() {
        return new ArrayList<>(allLocationNames);
    }
}

package com.easyfarming.customrun;

import com.easyfarming.core.Teleport;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import net.runelite.client.config.ConfigManager;

import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;

/**
 * Persists instruction text overrides for navigation and farming steps.
 * <ul>
 *   <li>Nav keys: {@code locationName|teleportEnumOption} so shared teleport methods
 *       (e.g. Camelot) can differ at Seers Village vs Catherby.</li>
 *   <li>Farming/step keys: {@code step|defaultText} so e.g. "Harvest Herbs." can be customized.</li>
 * </ul>
 */
public class NavigationTextOverrides {
    private static final String CONFIG_GROUP = "farminghelper";
    private static final String KEY_NAV_TEXT_OVERRIDES = "navTextOverrides";
    private static final String STEP_PREFIX = "step|";
    private static final Type MAP_TYPE = new TypeToken<HashMap<String, String>>() {}.getType();

    private final ConfigManager configManager;
    private final Gson gson;

    public NavigationTextOverrides(ConfigManager configManager, Gson gson) {
        this.configManager = configManager;
        this.gson = gson;
    }

    /** Package-visible for unit tests. */
    static String key(String locationName, String teleportEnumOption) {
        if (locationName == null) {
            locationName = "";
        }
        if (teleportEnumOption == null) {
            teleportEnumOption = "";
        }
        return locationName + "|" + teleportEnumOption;
    }

    /** Package-visible for unit tests. */
    static String stepKey(String defaultText) {
        return STEP_PREFIX + (defaultText != null ? defaultText : "");
    }

    public Map<String, String> loadAll() {
        String json = configManager.getConfiguration(CONFIG_GROUP, KEY_NAV_TEXT_OVERRIDES);
        if (json == null || json.isEmpty()) {
            return new HashMap<>();
        }
        try {
            Map<String, String> map = gson.fromJson(json, MAP_TYPE);
            return map != null ? map : new HashMap<>();
        } catch (Exception e) {
            return new HashMap<>();
        }
    }

    private void saveAll(Map<String, String> map) {
        configManager.setConfiguration(CONFIG_GROUP, KEY_NAV_TEXT_OVERRIDES, gson.toJson(map != null ? map : new HashMap<>()));
    }

    public String getOverride(String locationName, String teleportEnumOption) {
        return loadAll().get(key(locationName, teleportEnumOption));
    }

    public void setOverride(String locationName, String teleportEnumOption, String text) {
        Map<String, String> map = loadAll();
        String k = key(locationName, teleportEnumOption);
        if (text == null || text.trim().isEmpty()) {
            map.remove(k);
        } else {
            map.put(k, text);
        }
        saveAll(map);
    }

    public void clearOverride(String locationName, String teleportEnumOption) {
        Map<String, String> map = loadAll();
        map.remove(key(locationName, teleportEnumOption));
        saveAll(map);
    }

    /**
     * Returns the override if present, otherwise the teleport's built-in description.
     */
    public String resolve(String locationName, Teleport teleport) {
        if (teleport == null) {
            return "";
        }
        String override = getOverride(locationName, teleport.getEnumOption());
        if (override != null && !override.isEmpty()) {
            return override;
        }
        return teleport.getDescription() != null ? teleport.getDescription() : "";
    }

    public String getStepOverride(String defaultText) {
        return loadAll().get(stepKey(defaultText));
    }

    public void setStepOverride(String defaultText, String text) {
        Map<String, String> map = loadAll();
        String k = stepKey(defaultText);
        if (text == null || text.trim().isEmpty()) {
            map.remove(k);
        } else {
            map.put(k, text);
        }
        saveAll(map);
    }

    public void clearStepOverride(String defaultText) {
        Map<String, String> map = loadAll();
        map.remove(stepKey(defaultText));
        saveAll(map);
    }

    /**
     * Returns the step override if present, otherwise {@code defaultText} (or empty if null).
     */
    public String resolveStep(String defaultText) {
        String override = getStepOverride(defaultText);
        if (override != null && !override.isEmpty()) {
            return override;
        }
        return defaultText != null ? defaultText : "";
    }
}

