package com.easyfarming.overlays.highlighting;

import com.easyfarming.EasyFarmingPlugin;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.Overlay;
import com.easyfarming.utils.Constants;

import javax.inject.Inject;
import java.awt.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Handles highlighting of game objects in the world.
 * Caches scene lookups per (objectId, region, plane) to avoid full scene scans every frame,
 * which caused severe FPS drops when e.g. showing "Rake weeds" overlay (issue #63).
 * Multi-tile GameObjects are kept only on their SceneMinLocation tile so allotment/hops
 * patches are not redrawn once per occupied tile (issue #101).
 */
public class GameObjectHighlighter {
    private final Client client;
    private final EasyFarmingPlugin plugin;

    /** Cache of objectId -> list of game objects in current scene. */
    private final Map<Integer, List<GameObject>> objectCache = new HashMap<>();
    /** Cache of objectId -> list of decorative objects (some tree patches are decorative, not game objects). */
    private final Map<Integer, List<DecorativeObject>> decorativeObjectCache = new HashMap<>();
    /** Cache of objectId -> list of ground objects (empty tree patch ready for sapling is often a ground object). */
    private final Map<Integer, List<GroundObject>> groundObjectCache = new HashMap<>();
    /** Scene key when cache was built: regionId * 10 + plane. */
    private int lastSceneKey = -1;

    @Inject
    public GameObjectHighlighter(Client client, EasyFarmingPlugin plugin) {
        this.client = client;
        this.plugin = plugin;
    }

    /**
     * Finds all game objects with the specified ID in the current scene.
     * Results are cached per scene (region + plane); cache is cleared when the player
     * changes region or plane so we do not scan the full 104x104 scene every frame.
     */
    public List<GameObject> findGameObjectsByID(int objectID) {
        if (client.getLocalPlayer() == null) {
            return new ArrayList<>();
        }
        WorldView wv = client.getTopLevelWorldView();
        if (wv == null || wv.getScene() == null) {
            return new ArrayList<>();
        }
        int plane = wv.getPlane();
        int regionId = client.getLocalPlayer().getWorldLocation().getRegionID();
        int sceneKey = regionId * 10 + plane;

        if (sceneKey != lastSceneKey) {
            objectCache.clear();
            decorativeObjectCache.clear();
            groundObjectCache.clear();
            lastSceneKey = sceneKey;
        }

        List<GameObject> cached = objectCache.get(objectID);
        if (cached != null) {
            return cached;
        }

        List<GameObject> gameObjects = new ArrayList<>();
        Tile[][][] tiles = wv.getScene().getTiles();
        for (int x = 0; x < Constants.SCENE_SIZE; x++) {
            for (int y = 0; y < Constants.SCENE_SIZE; y++) {
                Tile tile = tiles[plane][x][y];
                if (tile == null) {
                    continue;
                }
                for (GameObject gameObject : tile.getGameObjects()) {
                    // Multi-tile objects appear on every occupied tile; only keep the SW/min anchor
                    // (same pattern as RuneLite DevToolsOverlay) to avoid drawing N overlapping clickboxes.
                    if (gameObject != null
                            && isGameObjectAnchorTile(gameObject.getSceneMinLocation(), tile.getSceneLocation())
                            && objectIdMatches(gameObject.getId(), objectID)) {
                        gameObjects.add(gameObject);
                    }
                }
            }
        }
        objectCache.put(objectID, gameObjects);
        return gameObjects;
    }

    /**
     * Returns true when {@code tileSceneLocation} is the southwest/min tile of a (possibly multi-tile)
     * game object. Package-visible for unit tests.
     */
    static boolean isGameObjectAnchorTile(net.runelite.api.Point sceneMinLocation,
                                          net.runelite.api.Point tileSceneLocation) {
        return sceneMinLocation != null
                && tileSceneLocation != null
                && sceneMinLocation.equals(tileSceneLocation);
    }

    /**
     * Finds decorative objects with the given ID (same matching rules as {@link #findGameObjectsByID}).
     */
    public List<DecorativeObject> findDecorativeObjectsByID(int objectID) {
        if (client.getLocalPlayer() == null) {
            return new ArrayList<>();
        }
        WorldView wv = client.getTopLevelWorldView();
        if (wv == null || wv.getScene() == null) {
            return new ArrayList<>();
        }
        int plane = wv.getPlane();
        int regionId = client.getLocalPlayer().getWorldLocation().getRegionID();
        int sceneKey = regionId * 10 + plane;

        if (sceneKey != lastSceneKey) {
            objectCache.clear();
            decorativeObjectCache.clear();
            groundObjectCache.clear();
            lastSceneKey = sceneKey;
        }

        List<DecorativeObject> cached = decorativeObjectCache.get(objectID);
        if (cached != null) {
            return cached;
        }

        List<DecorativeObject> decorativeObjects = new ArrayList<>();
        Tile[][][] tiles = wv.getScene().getTiles();
        for (int x = 0; x < Constants.SCENE_SIZE; x++) {
            for (int y = 0; y < Constants.SCENE_SIZE; y++) {
                Tile tile = tiles[plane][x][y];
                if (tile == null) {
                    continue;
                }
                DecorativeObject decorativeObject = tile.getDecorativeObject();
                if (decorativeObject != null && objectIdMatches(decorativeObject.getId(), objectID)) {
                    decorativeObjects.add(decorativeObject);
                }
            }
        }
        decorativeObjectCache.put(objectID, decorativeObjects);
        return decorativeObjects;
    }

    /**
     * Finds ground objects with the given ID (e.g. cleared tree patch soil — use sapling — is often a ground object).
     */
    public List<GroundObject> findGroundObjectsByID(int objectID) {
        if (client.getLocalPlayer() == null) {
            return new ArrayList<>();
        }
        WorldView wv = client.getTopLevelWorldView();
        if (wv == null || wv.getScene() == null) {
            return new ArrayList<>();
        }
        int plane = wv.getPlane();
        int regionId = client.getLocalPlayer().getWorldLocation().getRegionID();
        int sceneKey = regionId * 10 + plane;

        if (sceneKey != lastSceneKey) {
            objectCache.clear();
            decorativeObjectCache.clear();
            groundObjectCache.clear();
            lastSceneKey = sceneKey;
        }

        List<GroundObject> cached = groundObjectCache.get(objectID);
        if (cached != null) {
            return cached;
        }

        List<GroundObject> groundObjects = new ArrayList<>();
        Tile[][][] tiles = wv.getScene().getTiles();
        for (int x = 0; x < Constants.SCENE_SIZE; x++) {
            for (int y = 0; y < Constants.SCENE_SIZE; y++) {
                Tile tile = tiles[plane][x][y];
                if (tile == null) {
                    continue;
                }
                GroundObject groundObject = tile.getGroundObject();
                if (groundObject != null && objectIdMatches(groundObject.getId(), objectID)) {
                    groundObjects.add(groundObject);
                }
            }
        }
        groundObjectCache.put(objectID, groundObjects);
        return groundObjects;
    }

    /**
     * Returns true if the scene object id matches the target (including impostor/resolved composition).
     * Farming patches can use different scene IDs depending on state; composition id matches the base object.
     * Checks both directions: scene object may be a variant of target, or target may be a variant of scene object.
     */
    private boolean objectIdMatches(int sceneId, int targetId) {
        if (sceneId == targetId) {
            return true;
        }
        try {
            // Is the scene object a variant of the target? (scene's base == target)
            ObjectComposition comp = client.getObjectDefinition(sceneId);
            if (comp != null) {
                while (comp.getImpostor() != null) {
                    comp = comp.getImpostor();
                }
                if (comp.getId() == targetId) {
                    return true;
                }
            }
            // Is the target a variant of the scene object? (target's base == scene) - e.g. Farming Guild herb 33979
            comp = client.getObjectDefinition(targetId);
            if (comp != null) {
                while (comp.getImpostor() != null) {
                    comp = comp.getImpostor();
                }
                if (comp.getId() == sceneId) {
                    return true;
                }
            }
            return false;
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Draws the clickbox for a game object.
     * Handles null/invalid objects gracefully (e.g. when patch is transitioning).
     */
    public void drawGameObjectClickbox(Graphics2D graphics, GameObject gameObject, Color color) {
        drawTileObjectClickbox(graphics, gameObject, color);
    }

    /**
     * Draws highlight for any tile object. Uses convex hull when clickbox is null (e.g. empty tree patch ready for sapling).
     */
    public void drawTileObjectClickbox(Graphics2D graphics, TileObject tileObject, Color color) {
        if (tileObject == null) {
            return;
        }
        try {
            Shape shape = tileObject.getClickbox();
            if (shape == null) {
                if (tileObject instanceof GameObject) {
                    shape = ((GameObject) tileObject).getConvexHull();
                } else if (tileObject instanceof DecorativeObject) {
                    shape = ((DecorativeObject) tileObject).getConvexHull();
                } else if (tileObject instanceof GroundObject) {
                    shape = ((GroundObject) tileObject).getConvexHull();
                }
            }
            if (shape != null) {
                graphics.setColor(color);
                graphics.draw(shape);
                graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), color.getAlpha() / 5));
                graphics.fill(shape);
            }
        } catch (Exception e) {
            // Ignore errors when object is transitioning (e.g. patch just cleared)
        }
    }

    /**
     * Draws highlights for all scene objects matching {@code objectId} without allocating an overlay.
     */
    public void renderGameObjectHighlight(Graphics2D graphics, int objectId, Color color) {
        for (GameObject gameObject : findGameObjectsByID(objectId)) {
            drawGameObjectClickbox(graphics, gameObject, color);
        }
        for (DecorativeObject decorativeObject : findDecorativeObjectsByID(objectId)) {
            drawTileObjectClickbox(graphics, decorativeObject, color);
        }
        for (GroundObject groundObject : findGroundObjectsByID(objectId)) {
            drawTileObjectClickbox(graphics, groundObject, color);
        }
    }

    /**
     * Draws highlights for multiple object ids (each id uses the scene cache from {@link #findGameObjectsByID}).
     */
    public void renderGameObjectHighlights(Graphics2D graphics, Iterable<Integer> objectIds, Color color) {
        for (Integer objectId : objectIds) {
            if (objectId != null) {
                renderGameObjectHighlight(graphics, objectId, color);
            }
        }
    }

    /**
     * Creates an overlay that highlights a game object by ID.
     */
    public Overlay highlightGameObject(int objectId, Color color) {
        return new Overlay() {
            @Override
            public Dimension render(Graphics2D graphics) {
                renderGameObjectHighlight(graphics, objectId, color);
                return null;
            }
        };
    }
}

package com.easyfarming.overlays.highlighting;

import com.easyfarming.EasyFarmingOverlay;
import com.easyfarming.EasyFarmingConfig;
import com.easyfarming.overlays.utils.ColorProvider;
import com.easyfarming.utils.Constants;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.HashSet;

/**
 * Handles highlighting of items in inventory and various item-related highlights.
 */
public class ItemHighlighter {
    private final Client client;
    private final ItemManager itemManager;
    private final EasyFarmingOverlay farmingHelperOverlay;
    private final EasyFarmingConfig config;
    private final ColorProvider colorProvider;

    @Inject
    public ItemHighlighter(Client client, ItemManager itemManager, EasyFarmingOverlay farmingHelperOverlay,
                          EasyFarmingConfig config, ColorProvider colorProvider) {
        this.client = client;
        this.itemManager = itemManager;
        this.farmingHelperOverlay = farmingHelperOverlay;
        this.config = config;
        this.colorProvider = colorProvider;
    }

    /**
     * Retrieves inventory items and corresponding widgets for slot-based highlighting.
     * @return pair of items and widgets, or null if inventory/widget not available
     */
    private InventoryItemsAndWidgets getInventoryItemsAndWidgets() {
        net.runelite.api.ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null) {
            return null;
        }
        Item[] items = inventory.getItems();
        Widget inventoryWidget = client.getWidget(InterfaceID.INVENTORY);
        if (inventoryWidget == null) {
            inventoryWidget = client.getWidget(149, 0);
        }
        if (inventoryWidget == null) {
            return null;
        }
        Widget[] children = inventoryWidget.getChildren();
        Widget[] dynamicChildren = inventoryWidget.getDynamicChildren();
        Widget[] childrenToUse = (dynamicChildren != null && dynamicChildren.length > 0) ? dynamicChildren : children;
        if (childrenToUse == null) {
            return null;
        }
        return new InventoryItemsAndWidgets(items, childrenToUse);
    }

    private static final class InventoryItemsAndWidgets {
        final Item[] items;
        final Widget[] widgets;
        InventoryItemsAndWidgets(Item[] items, Widget[] widgets) {
            this.items = items;
            this.widgets = widgets;
        }
    }

    /**
     * Highlights an item in the inventory by its ID.
     * Uses master's approach: match by slot index (ItemContainer + widget children) so highlighting is reliable.
     */
    public void itemHighlight(Graphics2D graphics, int itemID, Color color) {
        InventoryItemsAndWidgets data = getInventoryItemsAndWidgets();
        if (data == null) {
            return;
        }
        Item[] items = data.items;
        Widget[] childrenToUse = data.widgets;
        for (int i = 0; i < items.length && i < childrenToUse.length; i++) {
            Item item = items[i];
            if (item != null && itemMatchesTarget(item.getId(), itemID)) {
                Widget itemWidget = childrenToUse[i];
                if (itemWidget != null) {
                    drawHighlightOnWidget(graphics, itemWidget, color);
                }
            }
        }
    }

    /**
     * Highlights compost in inventory for the selected compost type.
     * For Bottomless: highlights empty and all filled bottomless bucket variants.
     * For Compost/Supercompost/Ultracompost: highlights that bucket type and all bottomless variants (any tier).
     */
    public void highlightCompost(Graphics2D graphics, int selectedCompostId, Color color) {
        List<Integer> idsToHighlight = new ArrayList<>();
        if (selectedCompostId == ItemID.BOTTOMLESS_COMPOST_BUCKET) {
            idsToHighlight.addAll(farmingHelperOverlay.getBottomlessCompostBucketIds());
        } else if (selectedCompostId == ItemID.BUCKET_COMPOST
                || selectedCompostId == ItemID.BUCKET_SUPERCOMPOST
                || selectedCompostId == ItemID.BUCKET_ULTRACOMPOST) {
            idsToHighlight.add(selectedCompostId);
            idsToHighlight.addAll(farmingHelperOverlay.getBottomlessCompostBucketIds());
        } else {
            idsToHighlight.add(selectedCompostId);
        }
        highlightInventorySlotsWithIds(graphics, idsToHighlight, color);
    }

    /**
     * Highlights every inventory slot whose item matches any of the given IDs (with variant handling for compost etc.).
     * Uses master's index-based approach: ItemContainer slots + widget children by index.
     */
    public void highlightInventorySlotsWithIds(Graphics2D graphics, List<Integer> targetIds, Color color) {
        if (targetIds == null || targetIds.isEmpty()) {
            return;
        }
        Set<Integer> set = new HashSet<>(targetIds);
        InventoryItemsAndWidgets data = getInventoryItemsAndWidgets();
        if (data == null) {
            return;
        }
        Item[] items = data.items;
        Widget[] childrenToUse = data.widgets;
        for (int i = 0; i < items.length && i < childrenToUse.length; i++) {
            Item item = items[i];
            if (item != null && itemMatchesAny(item.getId(), set)) {
                Widget itemWidget = childrenToUse[i];
                if (itemWidget != null) {
                    drawHighlightOnWidget(graphics, itemWidget, color);
                }
            }
        }
    }

    private void drawHighlightOnWidget(Graphics2D graphics, Widget w, Color color) {
        Rectangle bounds = w.getBounds();
        if (bounds != null && bounds.width > 0 && bounds.height > 0) {
            graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), 100));
            graphics.fill(bounds);
            graphics.setColor(color);
            graphics.draw(bounds);
        }
    }

    private boolean itemMatchesTarget(int itemId, int targetId) {
        if (itemId == targetId) {
            return true;
        }
        if (itemManager != null) {
            int canonical = itemManager.canonicalize(itemId);
            if (canonical == targetId) {
                return true;
            }
        }
        return isQuetzalWhistleHighlight(itemId, targetId)
                || isExplorersRingHighlight(itemId, targetId)
                || isArdyCloakHighlight(itemId, targetId)
                || isFarmingCapeHighlight(itemId, targetId)
                || isSkillsNecklaceHighlight(itemId, targetId)
                || isNecklaceOfPassageHighlight(itemId, targetId)
                || isBottomlessBucketHighlight(itemId, targetId)
                || isCombatBraceletHighlight(itemId, targetId);
    }

    private boolean itemMatchesAny(int itemId, Set<Integer> targetIds) {
        for (Integer targetId : targetIds) {
            if (itemMatchesTarget(itemId, targetId)) return true;
        }
        return false;
    }

    /**
     * Checks if an item ID matches a quetzal whistle highlight pattern.
     */
    private boolean isQuetzalWhistleHighlight(int itemId, int targetId) {
        return farmingHelperOverlay.isQuetzalWhistle(itemId) && farmingHelperOverlay.isQuetzalWhistle(targetId);
    }

    /**
     * Checks if an item ID matches an Explorer's Ring highlight pattern.
     */
    private boolean isExplorersRingHighlight(int itemId, int targetId) {
        return farmingHelperOverlay.isExplorersRing(itemId) && farmingHelperOverlay.isExplorersRing(targetId);
    }

    /**
     * Checks if an item ID matches an Ardougne Cloak highlight pattern.
     */
    private boolean isArdyCloakHighlight(int itemId, int targetId) {
        return farmingHelperOverlay.isArdyCloak(itemId) && farmingHelperOverlay.isArdyCloak(targetId);
    }

    /**
     * Checks if an item ID matches a Farming cape highlight pattern (untrimmed or trimmed).
     */
    private boolean isFarmingCapeHighlight(int itemId, int targetId) {
        return farmingHelperOverlay.isFarmingCape(itemId) && farmingHelperOverlay.isFarmingCape(targetId);
    }

    /**
     * Checks if an item ID matches a Skills Necklace highlight pattern.
     */
    private boolean isSkillsNecklaceHighlight(int itemId, int targetId) {
        return farmingHelperOverlay.isSkillsNecklace(itemId) && farmingHelperOverlay.isSkillsNecklace(targetId);
    }

    private boolean isNecklaceOfPassageHighlight(int itemId, int targetId) {
        return farmingHelperOverlay.isNecklaceOfPassage(itemId) && farmingHelperOverlay.isNecklaceOfPassage(targetId);
    }

    /**
     * Checks if an item ID matches a bottomless compost bucket highlight pattern (empty or filled tiers).
     */
    private boolean isBottomlessBucketHighlight(int itemId, int targetId) {
        if (targetId != ItemID.BOTTOMLESS_COMPOST_BUCKET) {
            return false;
        }
        return Constants.BOTTOMLESS_COMPOST_BUCKET_ITEM_IDS.contains(itemId);
    }

    /**
     * Checks if an item ID matches a Combat bracelet highlight pattern.
     * Handles all charged variants (2-6 charges).
     */
    private boolean isCombatBraceletHighlight(int itemId, int targetId) {
        return farmingHelperOverlay.isCombatBracelet(itemId) && farmingHelperOverlay.isCombatBracelet(targetId);
    }

    /**
     * Highlights allotment seeds in inventory.
     * Also highlights the Seed Box (seeds can be planted directly from it).
     */
    public void highlightAllotmentSeeds(Graphics2D graphics) {
        Color useItemColor = colorProvider.getHighlightUseItemWithAlpha();
        highlightInventorySlotsWithIds(graphics, farmingHelperOverlay.getAllotmentSeedIds(), useItemColor);
        highlightSeedBox(graphics, useItemColor);
    }

    /**
     * Highlights herb seeds in inventory.
     * Also highlights the Seed Box (seeds can be planted directly from it).
     */
    public void highlightHerbSeeds(Graphics2D graphics) {
        Color color = colorProvider.getHighlightUseItemWithAlpha();
        highlightInventorySlotsWithIds(graphics, farmingHelperOverlay.getHerbSeedIds(), color);
        highlightSeedBox(graphics, color);
    }

    /**
     * Highlights hops seeds in inventory.
     * Also highlights the Seed Box (seeds can be planted directly from it).
     */
    public void highlightHopsSeeds(Graphics2D graphics) {
        Color color = colorProvider.getHighlightUseItemWithAlpha();
        highlightInventorySlotsWithIds(graphics, farmingHelperOverlay.getHopsSeedIds(), color);
        highlightSeedBox(graphics, color);
    }

    /**
     * Highlights flower seeds in inventory (limpwurt, white lily, etc.).
     * Also highlights the Seed Box (seeds can be planted directly from it).
     */
    public void highlightFlowerSeeds(Graphics2D graphics) {
        Color color = colorProvider.getHighlightUseItemWithAlpha();
        highlightInventorySlotsWithIds(graphics, farmingHelperOverlay.getFlowerSeedIds(), color);
        highlightSeedBox(graphics, color);
    }

    private void highlightSeedBox(Graphics2D graphics, Color color) {
        highlightInventorySlotsWithIds(graphics, farmingHelperOverlay.getSeedBoxIds(), color);
    }

    /**
     * Highlights tree saplings in inventory.
     */
    public void highlightTreeSapling(Graphics2D graphics) {
        Color color = colorProvider.getHighlightUseItemWithAlpha();
        highlightInventorySlotsWithIds(graphics, farmingHelperOverlay.getTreeSaplingIds(), color);
    }

    /**
     * Highlights fruit tree saplings in inventory.
     */
    public void highlightFruitTreeSapling(Graphics2D graphics) {
        Color color = colorProvider.getHighlightUseItemWithAlpha();
        highlightInventorySlotsWithIds(graphics, farmingHelperOverlay.getFruitTreeSaplingIds(), color);
    }

    /**
     * Highlights teleport crystals in inventory.
     */
    public void highlightTeleportCrystal(Graphics2D graphics) {
        Color color = colorProvider.getLeftClickColorWithAlpha();
        for (Integer crystalId : farmingHelperOverlay.getTeleportCrystalIds()) {
            itemHighlight(graphics, crystalId, color);
        }
    }

    /**
     * Highlights skills necklaces in inventory.
     */
    public void highlightSkillsNecklace(Graphics2D graphics) {
        Color color = colorProvider.getRightClickColorWithAlpha();
        for (Integer necklaceId : farmingHelperOverlay.getSkillsNecklaceIds()) {
            itemHighlight(graphics, necklaceId, color);
        }
    }

    /**
     * Gets the selected compost item ID.
     */
    public Integer selectedCompostID() {
        EasyFarmingConfig.OptionEnumCompost selectedCompost = config.enumConfigCompost();
        switch (selectedCompost) {
            case Compost:
                return ItemID.BUCKET_COMPOST;
            case Supercompost:
                return ItemID.BUCKET_SUPERCOMPOST;
            case Ultracompost:
                return ItemID.BUCKET_ULTRACOMPOST;
            case Bottomless:
                return ItemID.BOTTOMLESS_COMPOST_BUCKET;
        }
        return -1;
    }

    /**
     * Checks if an item is in the inventory.
     * For bottomless compost bucket, also checks for filled variants.
     */
    public boolean isItemInInventory(int itemId) {
        net.runelite.api.ItemContainer inventory = client.getItemContainer(InventoryID.INV);

        Item[] items;
        if (inventory == null || inventory.getItems() == null) {
            items = new Item[0];
        } else {
            items = inventory.getItems();
        }

        for (Item item : items) {
            int checkItemId = item.getId();
            if (checkItemId == itemId) {
                return true;
            }
            // Bottomless compost bucket: treat every inventory variant as satisfying the requirement icon.
            if (itemId == ItemID.BOTTOMLESS_COMPOST_BUCKET) {
                if (Constants.BOTTOMLESS_COMPOST_BUCKET_ITEM_IDS.contains(checkItemId)) {
                    return true;
                }
            }
        }

        return false;
    }
}

package com.easyfarming.overlays.highlighting;

import com.easyfarming.overlays.utils.ColorProvider;
import net.runelite.api.Client;
import net.runelite.api.Menu;
import net.runelite.api.MenuEntry;
import net.runelite.client.util.ColorUtil;

import javax.inject.Inject;
import java.awt.*;

/**
 * Handles highlighting of menu entries (right-click options) for teleport items.
 * When the user right-clicks an item (e.g. Ardougne cloak, Skills necklace, Construction cape),
 * the correct submenu option (e.g. "Farm Teleport", "Farming Guild", "Teleport") is highlighted
 * in green so the user knows which option to click.
 */
public class MenuHighlighter {
    private final Client client;
    private final ColorProvider colorProvider;

    /** Solid green for menu option text so it is clearly visible. */
    private static final Color MENU_HIGHLIGHT_GREEN = new Color(0, 255, 0);

    @Inject
    public MenuHighlighter(Client client, ColorProvider colorProvider) {
        this.client = client;
        this.colorProvider = colorProvider;
    }

    /**
     * Highlights the right-click menu option the user should click (e.g. "Farm Teleport"
     * for Ardy cloak, "Farming Guild" for Skills necklace). Uses solid green text.
     */
    public void highlightRightClickOption(Graphics2D graphics, String option) {
        if (option == null || option.trim().isEmpty()) {
            return;
        }

        Menu menu = client.getMenu();
        if (menu == null) {
            return;
        }

        MenuEntry[] menuEntries = menu.getMenuEntries();
        if (menuEntries == null || menuEntries.length == 0) {
            return;
        }

        String search = option.trim().toLowerCase();

        for (int i = 0; i < menuEntries.length; i++) {
            MenuEntry entry = menuEntries[i];
            if (entry == null) {
                continue;
            }

            String optionText = entry.getOption();
            String target = entry.getTarget();

            if (!menuOptionMatches(optionText, target, search)) {
                continue;
            }

            if (optionText == null) {
                continue;
            }

            String rawText = optionText.replaceAll("<col=[^>]*>", "").replaceAll("</col>", "").trim();
            if (rawText.startsWith(">>>")) {
                break;
            }

            String highlightedText = ColorUtil.prependColorTag(rawText, MENU_HIGHLIGHT_GREEN);
            entry.setOption(highlightedText);
            menu.setMenuEntries(menuEntries);
            break;
        }
    }

    private boolean menuOptionMatches(String optionText, String target, String search) {
        if (search.isEmpty()) {
            return false;
        }
        if (optionText != null) {
            String opt = optionText.trim().toLowerCase();
            if (opt.equals(search)) {
                return true;
            }
            if (opt.startsWith(search + " ") || opt.startsWith(search + ">")) {
                return true;
            }
            if (opt.contains(" " + search + " ") || opt.endsWith(" " + search)) {
                return true;
            }
        }
        if (target != null) {
            String t = target.trim().toLowerCase();
            if (t.equals(search) || t.startsWith(search + " ")) {
                return true;
            }
        }
        return false;
    }
}

package com.easyfarming.overlays.highlighting;

import com.easyfarming.overlays.utils.ColorProvider;
import net.runelite.api.Client;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.NPC;

import javax.inject.Inject;
import java.awt.*;
import java.util.List;

/**
 * Handles highlighting of NPCs in the world.
 */
public class NPCHighlighter {
    private final Client client;
    private final ColorProvider colorProvider;

    @Inject
    public NPCHighlighter(Client client, ColorProvider colorProvider) {
        this.client = client;
        this.colorProvider = colorProvider;
    }

    /**
     * Highlights an NPC by name using their convex hull.
     */
    public void highlightNpc(Graphics2D graphics, String npcName) {
        IndexedObjectSet<? extends NPC> npcs = client.getTopLevelWorldView().npcs();

        if (npcs != null) {
            Color color = colorProvider.getLeftClickColorWithAlpha();
            for (NPC npc : npcs) {
                if (npc != null && npc.getName() != null && npc.getName().equals(npcName)) {
                    Shape convexHull = npc.getConvexHull();

                    if (convexHull != null) {
                        graphics.setColor(color);
                        graphics.draw(convexHull);
                        graphics.setColor(new Color(color.getRed(), 
                                                   color.getGreen(), 
                                                   color.getBlue(), 
                                                   color.getAlpha() / 5));
                        graphics.fill(convexHull);
                    }
                }
            }
        }
    }

    /**
     * Highlights multiple NPCs by name.
     */
    public void highlightNpcs(Graphics2D graphics, List<String> npcNames) {
        for (String npcName : npcNames) {
            highlightNpc(graphics, npcName);
        }
    }
}

