package com.easyfarming.overlays.utils;

import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import com.easyfarming.utils.Constants;

import javax.inject.Inject;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Utility class for finding game objects by name or ID.
 * Caches name lookups per scene to avoid full scene scans every frame (issue #86).
 */
public class GameObjectHelper {
    private final Client client;

    /** Cache of object name -> ids in current scene. */
    private final Map<String, List<Integer>> objectIdsByNameCache = new HashMap<>();
    /** Scene key when cache was built: regionId * 10 + plane. */
    private int lastSceneKey = -1;

    @Inject
    public GameObjectHelper(Client client) {
        this.client = client;
    }

    /**
     * Gets game object IDs by name in the current scene.
     */
    public List<Integer> getGameObjectIdsByName(String name) {
        if (client.getLocalPlayer() == null) {
            return new ArrayList<>();
        }
        WorldView topWv = client.getTopLevelWorldView();
        if (topWv == null || topWv.getScene() == null) {
            return new ArrayList<>();
        }

        int plane = topWv.getPlane();
        int regionId = client.getLocalPlayer().getWorldLocation().getRegionID();
        int sceneKey = regionId * 10 + plane;

        if (sceneKey != lastSceneKey) {
            objectIdsByNameCache.clear();
            lastSceneKey = sceneKey;
        }

        List<Integer> cached = objectIdsByNameCache.get(name);
        if (cached != null) {
            return cached;
        }

        List<Integer> foundObjectIds = new ArrayList<>();
        Tile[][][] tiles = topWv.getScene().getTiles();

        for (int x = 0; x < Constants.SCENE_SIZE; x++) {
            for (int y = 0; y < Constants.SCENE_SIZE; y++) {
                Tile tile = tiles[plane][x][y];
                if (tile == null) {
                    continue;
                }

                for (GameObject gameObject : tile.getGameObjects()) {
                    if (gameObject != null) {
                        ObjectComposition objectComposition = client.getObjectDefinition(gameObject.getId());
                        if (objectComposition != null && name.equals(objectComposition.getName())) {
                            foundObjectIds.add(gameObject.getId());
                        }
                    }
                }
            }
        }

        objectIdsByNameCache.put(name, foundObjectIds);
        return foundObjectIds;
    }
}

package com.easyfarming.overlays.utils;

import com.easyfarming.EasyFarmingPlugin;

import javax.inject.Inject;
import java.util.regex.Pattern;

/**
 * Utility class for checking patch states (composted, protected, etc.).
 */
public class PatchStateChecker {
    private static final String REGEX_COMPOST1 = "You treat the (herb patch|flower patch|allotment|tree patch|fruit tree patch|hops patch) with (compost|supercompost|ultracompost)\\.";
    private static final String REGEX_COMPOST2 = "This (herb patch|flower patch|allotment|tree patch|fruit tree patch|hops patch) has already been treated with (compost|supercompost|ultracompost)\\.";
    private static final String REGEX_COMPOST3 = "You treat the patch with (compost|supercompost|ultracompost)\\.";
    private static final String REGEX_COMPOST4 = "This patch has already been treated with (compost|supercompost|ultracompost)\\.";
    private static final Pattern COMPOST_PATTERN = Pattern.compile(REGEX_COMPOST1 + "|" + REGEX_COMPOST2 + "|" + REGEX_COMPOST3 + "|" + REGEX_COMPOST4);

    private static final String STANDARD_RESPONSE = "You pay the gardener ([0-9A-Za-z\\ ]+) to protect the patch\\.";
    private static final String FALADOR_ELITE_RESPONSE = "The gardener protects your tree for you, free of charge, as a token of gratitude for completing the ([A-Za-z\\ ]+)\\.";
    private static final Pattern PROTECTED_PATTERN = Pattern.compile(STANDARD_RESPONSE + "|" + FALADOR_ELITE_RESPONSE);

    private final EasyFarmingPlugin plugin;

    @Inject
    public PatchStateChecker(EasyFarmingPlugin plugin) {
        this.plugin = plugin;
    }

    /**
     * Checks if a patch has been composted based on chat messages.
     */
    public boolean patchIsComposted() {
        String lastMessage = plugin.getLastMessage();
        if (lastMessage == null || lastMessage.isEmpty()) {
            return false;
        }

        return COMPOST_PATTERN.matcher(lastMessage).matches();
    }

    /**
     * True when the last compost-related chat line refers to the regular tree patch (not the fruit tree patch).
     * Used so composting the tree at a location with both patches does not satisfy the fruit tree step.
     */
    public boolean patchIsCompostedForTreePatch() {
        String lastMessage = plugin.getLastMessage();
        if (lastMessage == null || lastMessage.isEmpty()) {
            return false;
        }
        if (!COMPOST_PATTERN.matcher(lastMessage).matches()) {
            return false;
        }
        if (lastMessage.contains("fruit tree patch")) {
            return false;
        }
        if (lastMessage.contains("tree patch")) {
            return true;
        }
        if (lastMessage.contains("herb patch") || lastMessage.contains("flower patch")
                || lastMessage.contains("allotment") || lastMessage.contains("hops patch")) {
            return false;
        }
        return isGenericPatchCompostMessage(lastMessage);
    }

    /**
     * True when the last compost-related chat line refers to the fruit tree patch (or an untyped "the patch" line).
     */
    public boolean patchIsCompostedForFruitTreePatch() {
        String lastMessage = plugin.getLastMessage();
        if (lastMessage == null || lastMessage.isEmpty()) {
            return false;
        }
        if (!COMPOST_PATTERN.matcher(lastMessage).matches()) {
            return false;
        }
        if (lastMessage.contains("fruit tree patch")) {
            return true;
        }
        if (lastMessage.contains("tree patch")) {
            return false;
        }
        if (lastMessage.contains("herb patch") || lastMessage.contains("flower patch")
                || lastMessage.contains("allotment") || lastMessage.contains("hops patch")) {
            return false;
        }
        return isGenericPatchCompostMessage(lastMessage);
    }

    private static boolean isGenericPatchCompostMessage(String lastMessage) {
        return lastMessage.contains("treat the patch with") || lastMessage.contains("This patch has already");
    }

    /**
     * Herb step: accept only herb-specific or untyped "the patch" compost lines (not tree/fruit/hops/etc.).
     */
    public boolean patchIsCompostedForHerbPatch() {
        String lastMessage = plugin.getLastMessage();
        if (lastMessage == null || lastMessage.isEmpty()) {
            return false;
        }
        if (!COMPOST_PATTERN.matcher(lastMessage).matches()) {
            return false;
        }
        if (lastMessage.contains("herb patch")) {
            return true;
        }
        if (lastMessage.contains("flower patch") || lastMessage.contains("fruit tree patch")
                || lastMessage.contains("hops patch") || lastMessage.contains("allotment")) {
            return false;
        }
        if (lastMessage.contains("tree patch")) {
            return false;
        }
        return isGenericPatchCompostMessage(lastMessage);
    }

    /**
     * Flower (limpwurt) step: accept only flower-specific or untyped "the patch" lines.
     */
    public boolean patchIsCompostedForFlowerPatch() {
        String lastMessage = plugin.getLastMessage();
        if (lastMessage == null || lastMessage.isEmpty()) {
            return false;
        }
        if (!COMPOST_PATTERN.matcher(lastMessage).matches()) {
            return false;
        }
        if (lastMessage.contains("flower patch")) {
            return true;
        }
        if (lastMessage.contains("herb patch") || lastMessage.contains("fruit tree patch")
                || lastMessage.contains("hops patch") || lastMessage.contains("allotment")) {
            return false;
        }
        if (lastMessage.contains("tree patch")) {
            return false;
        }
        return isGenericPatchCompostMessage(lastMessage);
    }

    /**
     * Hops step: accept only hops-specific or untyped "the patch" lines.
     */
    public boolean patchIsCompostedForHopsPatch() {
        String lastMessage = plugin.getLastMessage();
        if (lastMessage == null || lastMessage.isEmpty()) {
            return false;
        }
        if (!COMPOST_PATTERN.matcher(lastMessage).matches()) {
            return false;
        }
        if (lastMessage.contains("hops patch")) {
            return true;
        }
        if (lastMessage.contains("herb patch") || lastMessage.contains("flower patch")
                || lastMessage.contains("fruit tree patch") || lastMessage.contains("allotment")) {
            return false;
        }
        if (lastMessage.contains("tree patch")) {
            return false;
        }
        return isGenericPatchCompostMessage(lastMessage);
    }

    /**
     * Allotment north/south: accept allotment lines or generic "the patch". North→south transitions clear the
     * last message so one allotment compost line cannot satisfy the other half.
     */
    public boolean patchIsCompostedForAllotmentPatch() {
        String lastMessage = plugin.getLastMessage();
        if (lastMessage == null || lastMessage.isEmpty()) {
            return false;
        }
        if (!COMPOST_PATTERN.matcher(lastMessage).matches()) {
            return false;
        }
        if (lastMessage.contains("allotment")) {
            return true;
        }
        if (lastMessage.contains("herb patch") || lastMessage.contains("flower patch")
                || lastMessage.contains("fruit tree patch") || lastMessage.contains("hops patch")) {
            return false;
        }
        if (lastMessage.contains("tree patch")) {
            return false;
        }
        return isGenericPatchCompostMessage(lastMessage);
    }

    /**
     * Checks if a patch has been protected based on chat messages.
     */
    public boolean patchIsProtected() {
        String lastMessage = plugin.getLastMessage();
        if (lastMessage == null || lastMessage.isEmpty()) {
            return false;
        }

        return PROTECTED_PATTERN.matcher(lastMessage).matches();
    }
}

package com.easyfarming.overlays.utils;

import com.easyfarming.utils.Constants;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

import javax.inject.Inject;

/**
 * Utility class for widget-related operations.
 */
public class WidgetHelper {
    private final Client client;

    @Inject
    public WidgetHelper(Client client) {
        this.client = client;
    }

    /**
     * Gets the child index of a widget by searching for text after a colon.
     */
    public int getChildIndex(String searchText, Widget parentWidget) {
        if (parentWidget == null) {
            return -1;
        }

        Widget[] children = parentWidget.getChildren();

        if (children == null) {
            return -1;
        }

        for (int index = 0; index < children.length; index++) {
            Widget child = children[index];
            String text = child.getText();

            if (text != null) {
                int colonIndex = text.indexOf(':');

                if (colonIndex != -1 && colonIndex + 1 < text.length()) {
                    String textAfterColon = text.substring(colonIndex + 1).trim();

                    if (textAfterColon.equals(searchText)) {
                        return index;
                    }
                }
            }
        }

        return -1;
    }

    /**
     * Gets the child index for Portal Nexus widget.
     */
    public int getChildIndexPortalNexus(String searchText) {
        return getChildIndex(
            searchText,
            client.getWidget(Constants.WIDGET_PORTAL_NEXUS_PARENT, Constants.WIDGET_PORTAL_NEXUS_CHILD)
        );
    }

    /**
     * Gets the child index for Spirit Tree widget.
     */
    public int getChildIndexSpiritTree(String searchText) {
        return getChildIndex(
            searchText,
            client.getWidget(Constants.INTERFACE_SPIRIT_TREE, Constants.INTERFACE_SPIRIT_TREE_CHILD)
        );
    }

    /**
     * Checks if an interface is open.
     */
    public boolean isInterfaceOpen(int groupId, int childId) {
        Widget widget = client.getWidget(groupId, childId);
        return widget != null && !widget.isHidden();
    }

    /**
     * Dynamically detects the correct spellbook tab interface ID based on the current client mode.
     * @return The child ID for the magic spellbook tab, or -1 if not found
     */
    public int getSpellbookTabChildId() {
        if (isInterfaceOpen(161, 65)) {
            return 65;
        }
        if (isInterfaceOpen(164, 58)) {
            return 58;
        }
        if (isInterfaceOpen(161, 58)) {
            return 58;
        }
        if (isInterfaceOpen(164, 65)) {
            return 65;
        }
        return 65;
    }

    /**
     * Gets the correct group ID for the spellbook tab based on the current client mode.
     * @return The group ID for the spellbook tab
     */
    public int getSpellbookTabGroupId() {
        if (isInterfaceOpen(161, 65)) {
            return 161;
        }
        if (isInterfaceOpen(164, 58)) {
            return 164;
        }
        if (isInterfaceOpen(161, 58)) {
            return 161;
        }
        if (isInterfaceOpen(164, 65)) {
            return 164;
        }
        return 161;
    }

    /**
     * Gets the widget group ID for the spellbook icon in the tab bar.
     * Detects whether we're in fixed classic mode (548) or resizable mode (161/164).
     * @return The group ID for the tab bar containing the spellbook icon
     */
    public int getSpellbookIconGroupId() {
        // Check for fixed classic mode first (548)
        if (isInterfaceOpen(548, 63)) {
            return 548;
        }
        // Check for resizable mode (161 or 164)
        if (isInterfaceOpen(161, 65) || isInterfaceOpen(161, 58)) {
            return 161;
        }
        if (isInterfaceOpen(164, 58) || isInterfaceOpen(164, 65)) {
            return 164;
        }
        // Default to resizable mode
        return 161;
    }

    /**
     * Gets the child ID for the spellbook icon in the tab bar.
     * Based on screenshots:
     * - Resizable classic mode (161): child ID 72 (ICON6)
     * - Resizable modern mode (164): child ID 65 (ICON6)
     * - Fixed classic mode (548): child ID 77 (ICON6)
     * @return The child ID for the spellbook icon
     */
    public int getSpellbookIconChildId() {
        int groupId = getSpellbookIconGroupId();

        // Fixed classic mode uses widget 548, child 77
        if (groupId == 548) {
            return 77;
        }

        // Resizable modern mode (164) uses child ID 65
        if (groupId == 164) {
            return 65;
        }

        // Resizable classic mode (161) uses child ID 72
        return 72;
    }
}

package com.easyfarming.ui;

