/**
 * Detail view for a custom run: editable name, filter bar (2x3), then one sub-panel per location (patch icons + teleport).
 * No location dropdown: each location is its own sub-panel. Filter: yellow = show locations with that patch; green = enable that patch at all locations.
 */
public class CustomRunDetailPanel extends JPanel {
    private final EasyFarmingPlugin plugin;
    private final EasyFarmingPanel parentPanel;
    private final CustomRun customRun;
    /**
     * Name used to locate this run in storage on save (matches list entry until user renames and saves).
     * Updated after each successful save so subsequent saves replace the correct entry.
     */
    private String originalRunName;
    private final net.runelite.client.game.ItemManager itemManager;

    private final CustomRunFilterBar filterBar;
    private final JPanel locationsContainer = new JPanel();
    private final JTextField runNameField;
    private final StartStopJButton startButton;
    private final JCheckBox skipItemGatheringCheck;
    private final JButton skipStepButton;
    /** Ordered list of locations (saved order; see {@link #syncRunWithCatalog()}). */
    private final List<RunLocation> runLocationsInOrder = new ArrayList<>();
    private final Map<String, CustomRunLocationSubPanel> subPanelsByLocation = new LinkedHashMap<>();
    private String draggedLocationName;
    private AWTEventListener dragEndListener;
    /** Prevents re-entry when syncing/refreshing (e.g. combo firing during refreshFromRunLocation). */
    private boolean inRowChangedOrRefresh = false;
    /** When true, hide locations that have no enabled patches (reduces clutter). */
    private boolean hideEmptyLocations = false;
    /** Last location auto-expanded during an active run; used to expand/collapse only on location change. */
    private String lastAutoExpandedLocation = null;

    public CustomRunDetailPanel(EasyFarmingPlugin plugin, EasyFarmingPanel parentPanel,
                                CustomRun customRun,
                                net.runelite.client.game.ItemManager itemManager) {
        this.plugin = plugin;
        this.parentPanel = parentPanel;
        this.customRun = customRun;
        this.originalRunName = customRun.getName() != null ? customRun.getName() : "";
        this.itemManager = itemManager;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        filterBar = new CustomRunFilterBar(itemManager);
        filterBar.setOnFilterChanged(this::onFilterChanged);

        syncRunWithCatalog();

        JPanel headerPanel = new JPanel(new BorderLayout());
        headerPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        headerPanel.setBorder(new EmptyBorder(5, 5, 10, 5));

        JButton backButton = new JButton("<");
        backButton.setPreferredSize(new Dimension(40, 22));
        backButton.setFocusable(false);
        backButton.setToolTipText("Back to Overview");
        backButton.addActionListener(e -> parentPanel.showOverview());

        runNameField = new JTextField(customRun.getName() != null ? customRun.getName() : "New Run", 20);
        runNameField.setForeground(Color.WHITE);
        runNameField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        runNameField.setCaretColor(Color.WHITE);
        runNameField.setFont(net.runelite.client.ui.FontManager.getRunescapeBoldFont());
        runNameField.setBorder(BorderFactory.createEmptyBorder(2, 6, 2, 6));
        JButton saveButton = new JButton("Save");
        saveButton.setFocusable(false);
        saveButton.setToolTipText("Save run and stay on edit screen (saves current name and all locations as shown)");
        saveButton.addActionListener(e -> saveRun());
        JPanel titlePanel = new JPanel();
        titlePanel.setLayout(new BoxLayout(titlePanel, BoxLayout.Y_AXIS));
        titlePanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        // BorderLayout so the name field stretches to fill the available row width
        // (FlowLayout would keep it at the column-20 preferred width, which gets
        // clipped in the narrow RuneLite plugin panel and renders as an empty box).
        JPanel titleRow = new JPanel(new BorderLayout());
        titleRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        titleRow.add(runNameField, BorderLayout.CENTER);
        titlePanel.add(titleRow);
        JPanel saveRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 4));
        saveRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        saveRow.add(backButton);
        saveRow.add(saveButton);
        titlePanel.add(saveRow);
        headerPanel.add(titlePanel, BorderLayout.CENTER);

        JPanel headerButtons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 5, 0));
        headerButtons.setBackground(ColorScheme.DARK_GRAY_COLOR);

        skipItemGatheringCheck = new JCheckBox("Skip item checklist");
        skipItemGatheringCheck.setSelected(customRun.isSkipItemGathering());
        skipItemGatheringCheck.setFocusable(false);
        skipItemGatheringCheck.setBackground(ColorScheme.DARK_GRAY_COLOR);
        skipItemGatheringCheck.setForeground(Color.WHITE);
        skipItemGatheringCheck.setToolTipText("When enabled, starting this run skips \"Grab all the items needed\" and goes straight to teleport guidance.");
        skipItemGatheringCheck.addActionListener(e -> customRun.setSkipItemGathering(skipItemGatheringCheck.isSelected()));

        skipStepButton = new JButton("Skip current step");
        skipStepButton.setFocusable(false);
        skipStepButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        skipStepButton.setForeground(Color.WHITE);
        skipStepButton.setAlignmentX(Component.LEFT_ALIGNMENT);
        skipStepButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, skipStepButton.getPreferredSize().height));
        skipStepButton.setToolTipText("Skip the current step: item checklist, travel, or farming.");
        skipStepButton.addActionListener(e -> plugin.skipCurrentStep());
        skipStepButton.setVisible(false);

        startButton = new StartStopJButton(customRun.getName());
        startButton.setPreferredSize(new Dimension(80, 25));
        startButton.addActionListener(e -> {
            boolean toggleToStop = startButton.getText().equals("Start");
            startButton.setStartStopState(toggleToStop);
            if (toggleToStop) {
                // Commit config state to run so required items use it (no fallbacks)
                customRun.setIncludeSecateurs(filterBar.isSecateursIncluded());
                customRun.setIncludeDibber(filterBar.isDibberIncluded());
                customRun.setIncludeRake(filterBar.isRakeIncluded());
                customRun.setSkipItemGathering(skipItemGatheringCheck.isSelected());
                parentPanel.startCustomRun(customRun);
            } else {
                plugin.getFarmingTeleportOverlay().removeOverlay();
                plugin.setOverlayActive(false);
                refreshActiveRunControls();
            }
        });
        syncStartButtonState(startButton);
        headerButtons.add(startButton);
        headerPanel.add(headerButtons, BorderLayout.EAST);

        JLabel filterHint = new JLabel("Tools: grey = not included, green = included. Patch: yellow = filter, green = enable at all.");
        filterHint.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        filterHint.setFont(filterHint.getFont().deriveFont(10f));
        // Same eye icon for both modes. Red = hiding locations with no patches.
        final String eyeIcon = "\uD83D\uDC41";
        JToggleButton hideEmptyToggle = new JToggleButton(eyeIcon, false);
        hideEmptyToggle.setToolTipText(hideEmptyLocations
            ? "Hiding locations with no enabled patches (click to show all)"
            : "Show all locations for filter (click to hide locations with no patches)");
        hideEmptyToggle.setFocusable(false);
        hideEmptyToggle.setSelected(hideEmptyLocations);
        hideEmptyToggle.setOpaque(true);
        hideEmptyToggle.setBackground(hideEmptyLocations ? Color.RED : ColorScheme.DARKER_GRAY_COLOR);
        hideEmptyToggle.addItemListener(e -> {
            hideEmptyLocations = hideEmptyToggle.isSelected();
            hideEmptyToggle.setBackground(hideEmptyLocations ? Color.RED : ColorScheme.DARKER_GRAY_COLOR);
            hideEmptyToggle.setToolTipText(hideEmptyLocations
                ? "Hiding locations with no enabled patches (click to show all)"
                : "Show all locations for filter (click to hide locations with no patches)");
            refreshLocationVisibility();
        });
        JPanel filterOptionsRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 2));
        filterOptionsRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        filterOptionsRow.add(hideEmptyToggle);
        filterOptionsRow.add(skipItemGatheringCheck);
        filterOptionsRow.add(filterHint);
        JPanel northPanel = new JPanel();
        northPanel.setLayout(new BoxLayout(northPanel, BoxLayout.Y_AXIS));
        northPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        northPanel.add(headerPanel);
        northPanel.add(filterBar);
        northPanel.add(filterOptionsRow);
        northPanel.add(Box.createRigidArea(new Dimension(0, 6)));
        northPanel.add(skipStepButton);
        add(northPanel, BorderLayout.NORTH);

        locationsContainer.setLayout(new BoxLayout(locationsContainer, BoxLayout.Y_AXIS));
        locationsContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
        locationsContainer.setBorder(new EmptyBorder(0, 10, 10, 10));
        JScrollPane scrollPane = new JScrollPane(locationsContainer);
        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setBorder(null);
        scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        add(scrollPane, BorderLayout.CENTER);

        syncFilterStateFromRun();
        // Restore saved tool requirement state
        filterBar.setSecateursIncluded(customRun.isIncludeSecateurs());
        filterBar.setDibberIncluded(customRun.isIncludeDibber());
        filterBar.setRakeIncluded(customRun.isIncludeRake());
        refreshLocationVisibility();
        refreshActiveRunControls();
    }

    /** Update filter bar from run data: green if all enabled, yellow if some enabled, neutral if none. */
    private void syncFilterStateFromRun() {
        LocationCatalog catalog = plugin.getLocationCatalog();
        for (String patchType : PatchTypes.ALL) {
            boolean allEnabled = true;
            int someEnabled = 0;
            int locationsWithType = 0;
            for (RunLocation rl : runLocationsInOrder) {
                List<String> available = catalog.getPatchTypesAtLocation(rl.getLocationName());
                if (available != null && available.contains(patchType)) {
                    locationsWithType++;
                    if (rl.getPatchTypes().contains(patchType)) {
                        someEnabled++;
                    } else {
                        allEnabled = false;
                    }
                }
            }
            int state;
            if (locationsWithType > 0 && allEnabled) {
                state = 2; // green
            } else if (someEnabled > 0) {
                state = 1; // yellow (some but not all)
            } else {
                state = 0; // neutral
            }
            filterBar.setFilterState(patchType, state);
        }
    }

    /**
     * Ensure we have one {@link RunLocation} per catalog location, merging with the saved run.
     * Preserves the order stored in {@link CustomRun#getLocations()} (e.g. user drag-and-drop),
     * then appends any catalog locations missing from the save (new areas after a plugin update).
     */
    private void syncRunWithCatalog() {
        LocationCatalog catalog = plugin.getLocationCatalog();
        List<String> catalogNames = catalog.getAllLocationNames();
        Set<String> catalogNameSet = new LinkedHashSet<>(catalogNames);

        Map<String, RunLocation> byName = new LinkedHashMap<>();
        for (RunLocation rl : customRun.getLocations()) {
            if (rl.getLocationName() != null) {
                byName.put(rl.getLocationName(), rl);
            }
        }

        runLocationsInOrder.clear();
        Set<String> added = new HashSet<>();

        for (RunLocation rl : customRun.getLocations()) {
            String name = rl.getLocationName();
            if (name != null && catalogNameSet.contains(name)) {
                runLocationsInOrder.add(rl);
                added.add(name);
            }
        }

        for (String name : catalogNames) {
            if (!added.contains(name)) {
                RunLocation rl = byName.get(name);
                if (rl == null) {
                    String defaultTeleport = catalog.getDefaultTeleportOptionForNewRun(name);
                    rl = new RunLocation(name, defaultTeleport, new ArrayList<>());
                }
                runLocationsInOrder.add(rl);
                added.add(name);
            }
        }

        customRun.getLocations().clear();
        customRun.getLocations().addAll(runLocationsInOrder);
    }

    private void onFilterChanged(String patchType, int fromState, int toState) {
        if (toState == 2) {
            applyEnablePatchEverywhere(patchType);
        } else if (fromState == 2 && toState == 0) {
            applyDisablePatchEverywhere(patchType);
        }
        refreshLocationVisibility();
    }

    private void applyEnablePatchEverywhere(String patchType) {
        LocationCatalog catalog = plugin.getLocationCatalog();
        for (RunLocation rl : runLocationsInOrder) {
            List<String> available = catalog.getPatchTypesAtLocation(rl.getLocationName());
            if (available != null && available.contains(patchType)) {
                if (!rl.getPatchTypes().contains(patchType)) {
                    rl.getPatchTypes().add(patchType);
                }
            }
        }
        refreshSubPanels();
    }

    private void applyDisablePatchEverywhere(String patchType) {
        for (RunLocation rl : runLocationsInOrder) {
            rl.getPatchTypes().remove(patchType);
        }
        refreshSubPanels();
    }

    private void refreshSubPanels() {
        for (CustomRunLocationSubPanel sub : subPanelsByLocation.values()) {
            sub.refreshFromRunLocation();
        }
    }

    private void refreshLocationVisibility() {
        locationsContainer.removeAll();
        if (!filterBar.hasAnyYellowOrGreenFilter()) {
            JLabel noFilter = new JLabel("Select a filter (yellow or green) to show locations.");
            noFilter.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            locationsContainer.add(noFilter);
            locationsContainer.revalidate();
            locationsContainer.repaint();
            return;
        }
        java.util.Set<String> filterTypes = filterBar.getYellowOrGreenFilterTypes();
        LocationCatalog catalog = plugin.getLocationCatalog();
        for (RunLocation rl : runLocationsInOrder) {
            String name = rl.getLocationName();
            List<String> atLocation = catalog.getPatchTypesAtLocation(name);
            boolean show = false;
            for (String t : filterTypes) {
                if (atLocation != null && atLocation.contains(t)) {
                    show = true;
                    break;
                }
            }
            if (show && (!hideEmptyLocations || !rl.getPatchTypes().isEmpty())) {
                CustomRunLocationSubPanel sub = subPanelsByLocation.get(name);
                if (sub == null) {
                    sub = new CustomRunLocationSubPanel(plugin, itemManager, name, rl, this::onRowChanged, this::onLocationDragStart);
                    subPanelsByLocation.put(name, sub);
                } else {
                    sub.refreshFromRunLocation();
                }
                sub.refreshStepEditVisibility();
                locationsContainer.add(sub);
                locationsContainer.add(Box.createRigidArea(new Dimension(0, 6)));
            }
        }
        // Panels may have been recreated collapsed; re-apply active expand/collapse.
        lastAutoExpandedLocation = null;
        syncExpandedLocationToActiveRun();
        locationsContainer.revalidate();
        locationsContainer.repaint();
    }

    private void onRowChanged() {
        if (inRowChangedOrRefresh) return;
        inRowChangedOrRefresh = true;
        try {
            syncFilterStateFromRun();
            refreshLocationVisibility();
        } finally {
            inRowChangedOrRefresh = false;
        }
    }

    private void onLocationDragStart(String locationName) {
        this.draggedLocationName = locationName;
        if (dragEndListener != null) {
            Toolkit.getDefaultToolkit().removeAWTEventListener(dragEndListener);
        }
        dragEndListener = event -> {
            if (event.getID() != MouseEvent.MOUSE_RELEASED) return;
            if (!(event instanceof MouseEvent)) return;
            MouseEvent me = (MouseEvent) event;
            Toolkit.getDefaultToolkit().removeAWTEventListener(dragEndListener);
            dragEndListener = null;
            if (draggedLocationName == null) return;
            Component src = (Component) event.getSource();
            Point pt = new Point(me.getX(), me.getY());
            SwingUtilities.convertPointToScreen(pt, src);
            SwingUtilities.convertPointFromScreen(pt, locationsContainer);
            if (!locationsContainer.contains(pt)) {
                draggedLocationName = null;
                return;
            }
            Component at = locationsContainer.getComponentAt(pt);
            CustomRunLocationSubPanel dropPanel = findLocationSubPanelParent(at);
            if (dropPanel == null || dropPanel.getLocationName().equals(draggedLocationName)) {
                draggedLocationName = null;
                return;
            }
            reorderLocation(draggedLocationName, dropPanel.getLocationName());
            draggedLocationName = null;
        };
        Toolkit.getDefaultToolkit().addAWTEventListener(dragEndListener, java.awt.AWTEvent.MOUSE_EVENT_MASK);
    }

    private static CustomRunLocationSubPanel findLocationSubPanelParent(Component c) {
        while (c != null) {
            if (c instanceof CustomRunLocationSubPanel) return (CustomRunLocationSubPanel) c;
            c = c.getParent();
        }
        return null;
    }

    private void reorderLocation(String movedName, String dropBeforeName) {
        RunLocation moved = null;
        int fromIndex = -1;
        for (int i = 0; i < runLocationsInOrder.size(); i++) {
            if (runLocationsInOrder.get(i).getLocationName().equals(movedName)) {
                moved = runLocationsInOrder.get(i);
                fromIndex = i;
                break;
            }
        }
        if (moved == null) return;
        runLocationsInOrder.remove(fromIndex);
        int insertIndex = -1;
        for (int i = 0; i < runLocationsInOrder.size(); i++) {
            if (runLocationsInOrder.get(i).getLocationName().equals(dropBeforeName)) {
                insertIndex = i;
                break;
            }
        }
        if (insertIndex < 0) insertIndex = runLocationsInOrder.size();
        runLocationsInOrder.add(insertIndex, moved);
        customRun.getLocations().clear();
        customRun.getLocations().addAll(runLocationsInOrder);
        refreshLocationVisibility();
    }

    /** Sets the Start/Stop button to Start or Stop based on whether this run is the active custom run. */
    private void syncStartButtonState(StartStopJButton startButton) {
        boolean active = plugin.getFarmingTeleportOverlay().isCustomRunMode()
                && customRun.getName() != null
                && customRun.getName().equals(plugin.getFarmingTeleportOverlay().getActiveCustomRunName());
        startButton.setStartStopState(active);
    }

    /** Called when a run ends (e.g. from overlay) so the Start button returns to Start state. */
    public void refreshStartButtonState() {
        refreshActiveRunControls();
    }

    /** Sync Start/Stop and Skip visibility with whether this run is the active custom run. */
    public void refreshActiveRunControls() {
        syncStartButtonState(startButton);
        boolean active = plugin.getFarmingTeleportOverlay().isCustomRunMode()
                && customRun.getName() != null
                && customRun.getName().equals(plugin.getFarmingTeleportOverlay().getActiveCustomRunName());
        skipStepButton.setVisible(active);
        refreshStepEditButtons();
        revalidate();
        repaint();
    }

    /** Show the step-edit pencil only on the active location while this run is live. */
    public void refreshStepEditButtons() {
        for (CustomRunLocationSubPanel sub : subPanelsByLocation.values()) {
            sub.refreshStepEditVisibility();
        }
        syncExpandedLocationToActiveRun();
    }

    /**
     * While a custom run is active, expand the current location and collapse the others.
     * Only runs when the active location changes so manual expand/collapse mid-stop is not fought every frame.
     */
    private void syncExpandedLocationToActiveRun() {
        boolean runActive = plugin.getFarmingTeleportOverlay().isCustomRunMode()
                && customRun.getName() != null
                && customRun.getName().equals(plugin.getFarmingTeleportOverlay().getActiveCustomRunName());
        if (!runActive) {
            lastAutoExpandedLocation = null;
            return;
        }
        String activeLocation = plugin.getFarmingTeleportOverlay().getActiveLocationName();
        if (activeLocation == null || activeLocation.equals(lastAutoExpandedLocation)) {
            return;
        }
        lastAutoExpandedLocation = activeLocation;
        CustomRunLocationSubPanel activePanel = null;
        for (CustomRunLocationSubPanel sub : subPanelsByLocation.values()) {
            boolean isActive = CustomRunLocationSubPanel.shouldShowStepEditPencil(true, activeLocation, sub.getLocationName());
            sub.setExpanded(isActive);
            if (isActive) {
                activePanel = sub;
            }
        }
        if (activePanel != null) {
            CustomRunLocationSubPanel toReveal = activePanel;
            SwingUtilities.invokeLater(() -> toReveal.scrollRectToVisible(toReveal.getBounds()));
        }
        locationsContainer.revalidate();
        locationsContainer.repaint();
    }

    /** Saves the config state as it exists on button press: name, tool requirements, and all locations from UI. */
    private void saveRun() {
        // 1. Commit name from text field
        if (runNameField != null) {
            String currentName = runNameField.getText();
            if (currentName != null && !currentName.trim().isEmpty()) {
                customRun.setName(currentName.trim());
            }
        }
        // 2. Commit tool requirement state from filter bar
        customRun.setIncludeSecateurs(filterBar.isSecateursIncluded());
        customRun.setIncludeDibber(filterBar.isDibberIncluded());
        customRun.setIncludeRake(filterBar.isRakeIncluded());
        customRun.setSkipItemGathering(skipItemGatheringCheck.isSelected());
        // 3. Commit location order and ensure customRun.getLocations() matches current UI
        customRun.getLocations().clear();
        customRun.getLocations().addAll(runLocationsInOrder);
        // 4. Persist: load current list and update or add this run (only explicit Save reaches here)
        CustomRunStorage storage = plugin.getCustomRunStorage();
        List<CustomRun> runs = storage.load();
        int index = -1;
        for (int i = 0; i < runs.size(); i++) {
            if (Objects.equals(originalRunName, runs.get(i).getName())) {
                index = i;
                break;
            }
        }
        if (index >= 0) {
            runs.set(index, customRun);
        } else {
            runs.add(customRun);
        }
        storage.save(runs);
        originalRunName = customRun.getName() != null ? customRun.getName() : "";
    }
}

package com.easyfarming.ui;

import com.easyfarming.customrun.PatchTypes;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.game.ItemManager;
import net.runelite.api.gameval.ItemID;

import javax.swing.*;
import java.awt.*;
import java.util.List;

/**
 * Filter bar: tool row (secateurs, dibber, rake) then 2 rows of 3 patch-type icons.
 * Tool icons: grey = not included in run, green = included. Same logic flow as patch filters.
 * Patch icons cycle: neutral (0) -> yellow / filter (1) -> green / enable all (2) -> neutral.
 */
public class CustomRunFilterBar extends JPanel {
    private static final String TOOL_SECATEURS = "secateurs";
    private static final String TOOL_DIBBER = "dibber";
    private static final String TOOL_RAKE = "rake";
    private static final List<String> TOOL_KEYS = java.util.Arrays.asList(TOOL_SECATEURS, TOOL_DIBBER, TOOL_RAKE);
    private static final int PATCH_ICON_SIZE = 36;
    private static final int FILTER_STATES = 3;
    private static final int TOOL_STATES = 2; // 0 = grey (not included), 1 = green (included)
    /** Neutral = off, 1 = yellow (filter), 2 = green (enable everywhere). */
    private final int[] filterStates = new int[PatchTypes.ALL.size()];
    private final JButton[] filterButtons = new JButton[PatchTypes.ALL.size()];
    /** Tool filter: 0 = not included, 1 = included. */
    private final int[] toolStates = new int[TOOL_KEYS.size()];
    private final JButton[] toolButtons = new JButton[TOOL_KEYS.size()];
    private final ItemManager itemManager;
    private FilterChangeListener onFilterChanged;
    private ToolFilterChangeListener onToolFilterChanged;

    private static final Color YELLOW_FILTER = new Color(180, 160, 40);
    private static final Color GREEN_ENABLE = new Color(30, 60, 30);
    private static final int GRIMY_RANARR_WEED = 207;

    public CustomRunFilterBar(ItemManager itemManager) {
        this.itemManager = itemManager;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));

        JPanel toolRow = new JPanel(new GridLayout(1, 3, 6, 6));
        toolRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        for (int i = 0; i < TOOL_KEYS.size(); i++) {
            final String toolKey = TOOL_KEYS.get(i);
            final int index = i;
            JButton btn = makeToolFilterButton(toolKey, index);
            toolButtons[index] = btn;
            toolRow.add(btn);
        }
        add(toolRow);
        add(Box.createRigidArea(new Dimension(0, 4)));
        JSeparator divider = new JSeparator(SwingConstants.HORIZONTAL);
        divider.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
        divider.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
        add(divider);
        add(Box.createRigidArea(new Dimension(0, 4)));

        JPanel patchGrid = new JPanel(new GridLayout(2, 3, 6, 6));
        patchGrid.setBackground(ColorScheme.DARK_GRAY_COLOR);
        List<String> all = PatchTypes.ALL;
        for (int i = 0; i < all.size(); i++) {
            final String patchType = all.get(i);
            final int index = i;
            JButton btn = makeFilterButton(patchType, index);
            filterButtons[index] = btn;
            patchGrid.add(btn);
        }
        add(patchGrid);
    }

    public interface FilterChangeListener {
        void onFilterChanged(String patchType, int fromState, int toState);
    }

    public interface ToolFilterChangeListener {
        void onToolFilterChanged(String toolKey, int fromState, int toState);
    }

    public void setOnFilterChanged(FilterChangeListener listener) {
        this.onFilterChanged = listener;
    }

    public void setOnToolFilterChanged(ToolFilterChangeListener listener) {
        this.onToolFilterChanged = listener;
    }

    public boolean isSecateursIncluded() { return toolStates[TOOL_KEYS.indexOf(TOOL_SECATEURS)] == 1; }
    public boolean isDibberIncluded() { return toolStates[TOOL_KEYS.indexOf(TOOL_DIBBER)] == 1; }
    public boolean isRakeIncluded() { return toolStates[TOOL_KEYS.indexOf(TOOL_RAKE)] == 1; }

    /** Set tool included state (e.g. when loading a saved run). Updates button appearance. */
    public void setSecateursIncluded(boolean included) {
        setToolIncluded(TOOL_SECATEURS, included);
    }
    public void setDibberIncluded(boolean included) {
        setToolIncluded(TOOL_DIBBER, included);
    }
    public void setRakeIncluded(boolean included) {
        setToolIncluded(TOOL_RAKE, included);
    }
    private void setToolIncluded(String toolKey, boolean included) {
        int idx = TOOL_KEYS.indexOf(toolKey);
        if (idx >= 0) {
            toolStates[idx] = included ? 1 : 0;
            updateToolFilterButtonAppearance(toolButtons[idx], idx);
        }
    }

    public int getFilterState(String patchType) {
        int idx = PatchTypes.ALL.indexOf(patchType);
        return idx >= 0 ? filterStates[idx] : 0;
    }

    public boolean isFilterActive(String patchType) {
        return getFilterState(patchType) == 1;
    }

    public boolean isEnableAllActive(String patchType) {
        return getFilterState(patchType) == 2;
    }

    /** True if any filter is yellow (view filter). */
    public boolean hasAnyYellowFilter() {
        for (int s : filterStates) {
            if (s == 1) return true;
        }
        return false;
    }

    /** True if any filter is yellow or green (show location list). */
    public boolean hasAnyYellowOrGreenFilter() {
        for (int s : filterStates) {
            if (s == 1 || s == 2) return true;
        }
        return false;
    }

    /** Patch types that are currently yellow (filter). */
    public java.util.Set<String> getYellowFilterTypes() {
        java.util.Set<String> set = new java.util.LinkedHashSet<>();
        List<String> all = PatchTypes.ALL;
        for (int i = 0; i < filterStates.length; i++) {
            if (filterStates[i] == 1) set.add(all.get(i));
        }
        return set;
    }

    /** Patch types that are yellow or green (for showing which locations to list). */
    public java.util.Set<String> getYellowOrGreenFilterTypes() {
        java.util.Set<String> set = new java.util.LinkedHashSet<>();
        List<String> all = PatchTypes.ALL;
        for (int i = 0; i < filterStates.length; i++) {
            if (filterStates[i] == 1 || filterStates[i] == 2) set.add(all.get(i));
        }
        return set;
    }

    public void setFilterState(String patchType, int state) {
        int idx = PatchTypes.ALL.indexOf(patchType);
        if (idx >= 0 && state >= 0 && state < FILTER_STATES) {
            filterStates[idx] = state;
            updateFilterButtonAppearance(filterButtons[idx], idx);
        }
    }

    private JButton makeToolFilterButton(String toolKey, int index) {
        int itemId = itemIdForTool(toolKey);
        String label = toolDisplayName(toolKey);
        String tooltip = label + " (click: grey = not included, green = included)";
        JButton btn = new JButton();
        btn.setPreferredSize(new Dimension(PATCH_ICON_SIZE, PATCH_ICON_SIZE));
        btn.setFocusable(false);
        btn.setToolTipText(tooltip);
        updateToolFilterButtonAppearance(btn, index);
        btn.setOpaque(true);
        btn.setBorderPainted(false);
        if (itemManager != null) {
            itemManager.getImage(itemId).addTo(btn);
        } else {
            btn.setText(label);
        }
        btn.addActionListener(e -> {
            int fromState = toolStates[index];
            toolStates[index] = (toolStates[index] + 1) % TOOL_STATES;
            int toState = toolStates[index];
            updateToolFilterButtonAppearance(btn, index);
            if (onToolFilterChanged != null) onToolFilterChanged.onToolFilterChanged(toolKey, fromState, toState);
        });
        return btn;
    }

    private JButton makeFilterButton(String patchType, int index) {
        int itemId = itemIdForPatchType(patchType);
        String tooltip = displayName(patchType) + " (click: filter → enable all → off)";
        JButton btn = new JButton();
        btn.setPreferredSize(new Dimension(PATCH_ICON_SIZE, PATCH_ICON_SIZE));
        btn.setFocusable(false);
        btn.setToolTipText(tooltip);
        updateFilterButtonAppearance(btn, index);
        btn.setOpaque(true);
        btn.setBorderPainted(false);
        if (itemManager != null) {
            itemManager.getImage(itemId).addTo(btn);
        } else {
            btn.setText(displayName(patchType));
        }
        btn.addActionListener(e -> {
            int fromState = filterStates[index];
            filterStates[index] = (filterStates[index] + 1) % FILTER_STATES;
            int toState = filterStates[index];
            updateFilterButtonAppearance(btn, index);
            if (onFilterChanged != null) onFilterChanged.onFilterChanged(patchType, fromState, toState);
        });
        return btn;
    }

    private void updateToolFilterButtonAppearance(JButton btn, int index) {
        int state = toolStates[index];
        if (state == 0) {
            btn.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        } else {
            btn.setBackground(GREEN_ENABLE);
        }
    }

    private static int itemIdForTool(String toolKey) {
        if (TOOL_SECATEURS.equals(toolKey)) return ItemID.FAIRY_ENCHANTED_SECATEURS;
        if (TOOL_DIBBER.equals(toolKey)) return ItemID.DIBBER;
        if (TOOL_RAKE.equals(toolKey)) return ItemID.RAKE;
        return ItemID.RAKE;
    }

    private static String toolDisplayName(String toolKey) {
        if (TOOL_SECATEURS.equals(toolKey)) return "Secateurs";
        if (TOOL_DIBBER.equals(toolKey)) return "Seed dibber";
        if (TOOL_RAKE.equals(toolKey)) return "Rake";
        return toolKey;
    }

    private void updateFilterButtonAppearance(JButton btn, int index) {
        int state = filterStates[index];
        if (state == 0) {
            btn.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        } else if (state == 1) {
            btn.setBackground(YELLOW_FILTER);
        } else {
            btn.setBackground(GREEN_ENABLE);
        }
    }

    private static int itemIdForPatchType(String patchType) {
        switch (patchType) {
            case PatchTypes.HERB: return GRIMY_RANARR_WEED;
            case PatchTypes.FLOWER: return net.runelite.api.gameval.ItemID.LIMPWURT_ROOT;
            case PatchTypes.ALLOTMENT: return net.runelite.api.gameval.ItemID.WATERMELON;
            case PatchTypes.TREE: return net.runelite.api.gameval.ItemID.YEW_LOGS;
            case PatchTypes.FRUIT_TREE: return net.runelite.api.gameval.ItemID.PINEAPPLE;
            case PatchTypes.HOPS: return net.runelite.api.gameval.ItemID.BARLEY;
            default: return GRIMY_RANARR_WEED;
        }
    }

    private static String displayName(String patchType) {
        switch (patchType) {
            case PatchTypes.HERB: return "Herb";
            case PatchTypes.FLOWER: return "Flower";
            case PatchTypes.ALLOTMENT: return "Allotment";
            case PatchTypes.TREE: return "Tree";
            case PatchTypes.FRUIT_TREE: return "Fruit tree";
            case PatchTypes.HOPS: return "Hops";
            default: return patchType.replace("_", " ");
        }
    }
}

package com.easyfarming.ui;

import com.easyfarming.EasyFarmingPlugin;
import com.easyfarming.customrun.LocationCatalog;
import com.easyfarming.customrun.PatchTypes;
import com.easyfarming.customrun.RunLocation;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.game.ItemManager;
import net.runelite.api.gameval.ItemID;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;

/**
 * One editable RunLocation row: location dropdown and Remove; patch icons (toggleable); teleport dropdown below icons.
 */
public class CustomRunLocationRowPanel extends JPanel {
    private static final int PATCH_ICON_SIZE = 36;

    private final EasyFarmingPlugin plugin;
    private final ItemManager itemManager;
    private final RunLocation runLocation;
    private final Runnable onRemove;
    private final Runnable onChanged;

    private final JComboBox<String> locationCombo;
    private final JComboBox<String> teleportCombo;
    private final JPanel patchIconsPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 4));
    private final List<JButton> patchIconButtons = new ArrayList<>();
    private boolean refreshingFromRun;

    public CustomRunLocationRowPanel(EasyFarmingPlugin plugin, ItemManager itemManager, RunLocation runLocation,
                                    Runnable onRemove, Runnable onChanged) {
        this.plugin = plugin;
        this.itemManager = itemManager;
        this.runLocation = runLocation;
        this.onRemove = onRemove;
        this.onChanged = onChanged;
        this.refreshingFromRun = true;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setBorder(new EmptyBorder(5, 10, 5, 10));

        LocationCatalog catalog = plugin.getLocationCatalog();
        List<String> allNames = catalog.getAllLocationNames();

        JPanel topRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 0));
        topRow.setOpaque(false);

        JLabel locLabel = new JLabel("Location");
        locLabel.setForeground(Color.WHITE);
        topRow.add(locLabel);
        locationCombo = new JComboBox<>(allNames.toArray(new String[0]));
        locationCombo.setRenderer(enumRenderer());
        locationCombo.setSelectedItem(runLocation.getLocationName());
        if (locationCombo.getSelectedItem() == null && !allNames.isEmpty()) {
            locationCombo.setSelectedIndex(0);
        }
        locationCombo.addActionListener(e -> onLocationSelected());
        topRow.add(locationCombo);

        JButton removeBtn = new JButton("Remove");
        removeBtn.setFocusable(false);
        removeBtn.addActionListener(e -> {
            if (onRemove != null) onRemove.run();
        });
        topRow.add(removeBtn);

        add(topRow, BorderLayout.NORTH);

        patchIconsPanel.setOpaque(false);
        add(patchIconsPanel, BorderLayout.CENTER);

        JPanel teleportRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 6));
        teleportRow.setOpaque(false);
        JLabel teleLabel = new JLabel("Teleport");
        teleLabel.setForeground(Color.WHITE);
        teleportRow.add(teleLabel);
        teleportCombo = new JComboBox<>();
        refreshTeleportOptions();
        teleportCombo.setRenderer(enumRenderer());
        teleportCombo.addActionListener(e -> {
            Object sel = teleportCombo.getSelectedItem();
            if (sel != null) runLocation.setTeleportOption((String) sel);
            if (!refreshingFromRun && onChanged != null) onChanged.run();
        });
        teleportRow.add(teleportCombo);
        add(teleportRow, BorderLayout.SOUTH);

        onLocationSelected();
        refreshingFromRun = false;
    }

    private void onLocationSelected() {
        Object sel = locationCombo.getSelectedItem();
        String name = sel != null ? (String) sel : null;
        runLocation.setLocationName(name);
        refreshTeleportOptions();
        refreshPatchIcons();
        if (!refreshingFromRun && onChanged != null) onChanged.run();
    }

    private void refreshTeleportOptions() {
        LocationCatalog catalog = plugin.getLocationCatalog();
        String name = runLocation.getLocationName();
        List<String> opts = name != null ? catalog.getTeleportOptionsForLocation(name) : new ArrayList<>();
        teleportCombo.removeAllItems();
        for (String o : opts) teleportCombo.addItem(o);
        String current = runLocation.getTeleportOption();
        if (current != null && opts.contains(current)) {
            teleportCombo.setSelectedItem(current);
        } else if (!opts.isEmpty()) {
            teleportCombo.setSelectedIndex(0);
            runLocation.setTeleportOption(opts.get(0));
        }
    }

    private void refreshPatchIcons() {
        patchIconsPanel.removeAll();
        patchIconButtons.clear();
        LocationCatalog catalog = plugin.getLocationCatalog();
        String name = runLocation.getLocationName();
        List<String> available = name != null ? catalog.getPatchTypesAtLocation(name) : new ArrayList<>();
        List<String> selected = runLocation.getPatchTypes() != null ? runLocation.getPatchTypes() : new ArrayList<>();
        for (String patchType : available) {
            JButton iconBtn = makePatchIconButton(patchType, selected.contains(patchType));
            patchIconButtons.add(iconBtn);
            patchIconsPanel.add(iconBtn);
        }
        patchIconsPanel.revalidate();
        patchIconsPanel.repaint();
    }

    private JButton makePatchIconButton(String patchType, boolean selected) {
        int itemId = itemIdForPatchType(patchType);
        String tooltip = displayName(patchType);
        JButton btn = new JButton();
        btn.setPreferredSize(new Dimension(PATCH_ICON_SIZE, PATCH_ICON_SIZE));
        btn.setFocusable(false);
        btn.setToolTipText(tooltip);
        btn.setBackground(selected ? new Color(30, 60, 30) : ColorScheme.DARKER_GRAY_COLOR);
        btn.setForeground(Color.WHITE);
        btn.setOpaque(true);
        btn.setBorderPainted(false);
        if (itemManager != null) {
            itemManager.getImage(itemId).addTo(btn);
        } else {
            btn.setText(tooltip);
        }
        btn.addActionListener(e -> {
            List<String> types = runLocation.getPatchTypes();
            if (types == null) {
                types = new ArrayList<>();
                runLocation.setPatchTypes(types);
            }
            if (types.contains(patchType)) {
                types.remove(patchType);
            } else {
                types.add(patchType);
            }
            btn.setBackground(types.contains(patchType) ? new Color(30, 60, 30) : ColorScheme.DARKER_GRAY_COLOR);
            if (onChanged != null) onChanged.run();
        });
        return btn;
    }

    private static int itemIdForPatchType(String patchType) {
        switch (patchType) {
            case PatchTypes.HERB:
                return ItemID.UNIDENTIFIED_RANARR;
            case PatchTypes.FLOWER:
                return ItemID.LIMPWURT_ROOT;
            case PatchTypes.ALLOTMENT:
                return ItemID.WATERMELON;
            case PatchTypes.TREE:
                return ItemID.YEW_LOGS;
            case PatchTypes.FRUIT_TREE:
                return ItemID.PINEAPPLE;
            case PatchTypes.HOPS:
                return ItemID.BARLEY;
            default:
                return ItemID.UNIDENTIFIED_RANARR;
        }
    }

    private static String displayName(String patchType) {
        switch (patchType) {
            case PatchTypes.HERB: return "Herb";
            case PatchTypes.FLOWER: return "Flower";
            case PatchTypes.ALLOTMENT: return "Allotment";
            case PatchTypes.TREE: return "Tree";
            case PatchTypes.FRUIT_TREE: return "Fruit tree";
            case PatchTypes.HOPS: return "Hops";
            default: return patchType.replace("_", " ");
        }
    }

    private static DefaultListCellRenderer enumRenderer() {
        return new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus) {
                Component c = super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
                if (value != null) ((JLabel) c).setText(((String) value).replace("_", " "));
                return c;
            }
        };
    }
}

package com.easyfarming.ui;

import com.easyfarming.EasyFarmingPlugin;
import com.easyfarming.core.Location;
import com.easyfarming.core.Teleport;
import com.easyfarming.customrun.CurrentStepInstruction;
import com.easyfarming.customrun.LocationCatalog;
import com.easyfarming.customrun.NavigationTextOverrides;
import com.easyfarming.customrun.PatchTypes;
import com.easyfarming.customrun.RunLocation;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.game.ItemManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;

/**
 * One location as its own sub-panel: location name header (draggable for reorder), patch icons, teleport dropdown below.
 * Selected patch icons show in visit order and can be dragged to reorder; header can be collapsed to minimize the panel.
 */
public class CustomRunLocationSubPanel extends JPanel {
    private static final int PATCH_ICON_SIZE = 36;
    private static final int GRIMY_RANARR_WEED = 207;
    private static final int PATCH_DRAG_THRESHOLD_PX = 6;
    private static final String CLIENT_PROP_PATCH_TYPE = "patchType";

    private final EasyFarmingPlugin plugin;
    private final ItemManager itemManager;
    private final String locationName;
    private final RunLocation runLocation;
    private final Runnable onChanged;

    private final JComboBox<String> teleportCombo;
    private final JButton editStepTextButton;
    private final JPanel patchIconsPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 4));
    private final JPanel contentPanel = new JPanel(new BorderLayout());
    private boolean expanded = false;
    private final JLabel expandCollapseLabel = new JLabel("\u25B6");
    /** When true, programmatic refresh is in progress; do not fire onChanged to avoid re-entry loop. */
    private boolean refreshingFromRun = false;

    private String draggedPatchType = null;
    private Point patchDragPressPoint = null;
    private boolean patchDragMoved = false;

    public CustomRunLocationSubPanel(EasyFarmingPlugin plugin, ItemManager itemManager, String locationName,
                                    RunLocation runLocation, Runnable onChanged) {
        this(plugin, itemManager, locationName, runLocation, onChanged, null);
    }

    public CustomRunLocationSubPanel(EasyFarmingPlugin plugin, ItemManager itemManager, String locationName,
                                    RunLocation runLocation, Runnable onChanged,
                                    java.util.function.Consumer<String> onDragStart) {
        this.plugin = plugin;
        this.itemManager = itemManager;
        this.locationName = locationName;
        this.runLocation = runLocation;
        this.onChanged = onChanged;

        runLocation.setLocationName(locationName);

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setBorder(BorderFactory.createCompoundBorder(
                new LineBorder(ColorScheme.DARK_GRAY_COLOR, 1),
                new EmptyBorder(8, 10, 8, 10)));

        JPanel headerPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
        headerPanel.setOpaque(false);

        expandCollapseLabel.setForeground(Color.WHITE);
        expandCollapseLabel.setFont(expandCollapseLabel.getFont().deriveFont(Font.BOLD, 14f));
        expandCollapseLabel.setCursor(new Cursor(Cursor.HAND_CURSOR));
        expandCollapseLabel.setToolTipText("Expand");
        expandCollapseLabel.setBorder(new EmptyBorder(0, 0, 0, 6));
        expandCollapseLabel.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                toggleExpanded();
            }
        });
        headerPanel.add(expandCollapseLabel);

        if (onDragStart != null) {
            JLabel gripLabel = new JLabel("\u22EE");
            gripLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            gripLabel.setCursor(new Cursor(Cursor.MOVE_CURSOR));
            gripLabel.setToolTipText("Drag to reorder");
            gripLabel.addMouseListener(new MouseAdapter() {
                @Override
                public void mousePressed(MouseEvent e) {
                    onDragStart.accept(locationName);
                }
            });
            headerPanel.add(gripLabel);
        }
        JLabel nameLabel = new JLabel(locationName);
        nameLabel.setForeground(Color.WHITE);
        nameLabel.setFont(FontManager.getRunescapeBoldFont());
        if (onDragStart != null) {
            nameLabel.setCursor(new Cursor(Cursor.MOVE_CURSOR));
            nameLabel.addMouseListener(new MouseAdapter() {
                @Override
                public void mousePressed(MouseEvent e) {
                    onDragStart.accept(locationName);
                }
            });
        }
        headerPanel.add(nameLabel);
        add(headerPanel, BorderLayout.NORTH);

        contentPanel.setOpaque(false);
        patchIconsPanel.setOpaque(false);
        contentPanel.add(patchIconsPanel, BorderLayout.CENTER);

        JPanel teleportRow = new JPanel(new BorderLayout(8, 0));
        teleportRow.setOpaque(false);
        teleportRow.setBorder(new EmptyBorder(6, 0, 6, 0));
        JLabel teleLabel = new JLabel("Teleport");
        teleLabel.setForeground(Color.WHITE);
        teleportCombo = new JComboBox<>();
        refreshTeleportOptions();
        teleportCombo.setRenderer(new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus) {
                Component c = super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
                if (value != null) ((JLabel) c).setText(((String) value).replace("_", " "));
                return c;
            }
        });
        teleportCombo.addActionListener(e -> {
            if (refreshingFromRun) return;
            Object sel = teleportCombo.getSelectedItem();
            if (sel != null) runLocation.setTeleportOption((String) sel);
            if (onChanged != null) onChanged.run();
        });
        // Cap preferred width so long teleport names cannot push the pencil off the narrow panel.
        teleportCombo.setPrototypeDisplayValue("Camelot Teleport");

        JPanel teleportFields = new JPanel(new BorderLayout(8, 0));
        teleportFields.setOpaque(false);
        teleportFields.add(teleLabel, BorderLayout.WEST);
        teleportFields.add(teleportCombo, BorderLayout.CENTER);
        teleportRow.add(teleportFields, BorderLayout.CENTER);

        editStepTextButton = new JButton("\u270E");
        editStepTextButton.setToolTipText("Edit text for the current step");
        editStepTextButton.setFocusable(false);
        editStepTextButton.setMargin(new Insets(2, 6, 2, 6));
        editStepTextButton.setForeground(Color.WHITE);
        editStepTextButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        editStepTextButton.addActionListener(e -> openCurrentStepTextEditor());
        editStepTextButton.setVisible(false);
        teleportRow.add(editStepTextButton, BorderLayout.EAST);

        contentPanel.add(teleportRow, BorderLayout.SOUTH);

        add(contentPanel, BorderLayout.CENTER);

        contentPanel.setVisible(expanded);
        refreshPatchIcons();
    }

    private void toggleExpanded() {
        setExpanded(!expanded);
    }

    /**
     * Expand or collapse this location panel. No-op when already in the requested state.
     */
    public void setExpanded(boolean expand) {
        if (this.expanded == expand) {
            return;
        }
        this.expanded = expand;
        contentPanel.setVisible(expanded);
        expandCollapseLabel.setText(expanded ? "\u25BC" : "\u25B6");
        expandCollapseLabel.setToolTipText(expanded ? "Collapse" : "Expand");
        revalidate();
        repaint();
    }

    public boolean isExpanded() {
        return expanded;
    }

    public String getLocationName() {
        return locationName;
    }

    /**
     * Pencil is shown only while a custom run is active and this panel is the active location.
     * Package-visible for unit tests.
     */
    static boolean shouldShowStepEditPencil(boolean customRunActive, String activeLocationName, String panelLocationName) {
        return customRunActive
                && activeLocationName != null
                && activeLocationName.equals(panelLocationName);
    }

    /** Refresh pencil visibility from the live custom-run / current-location state. */
    public void refreshStepEditVisibility() {
        boolean runActive = plugin.getFarmingTeleportOverlay().isCustomRunMode();
        String activeLocation = plugin.getFarmingTeleportOverlay().getActiveLocationName();
        boolean show = shouldShowStepEditPencil(runActive, activeLocation, locationName);
        if (editStepTextButton.isVisible() != show) {
            editStepTextButton.setVisible(show);
            revalidate();
            repaint();
        }
    }

    private void refreshTeleportOptions() {
        LocationCatalog catalog = plugin.getLocationCatalog();
        List<String> opts = catalog.getTeleportOptionsForLocation(locationName);
        teleportCombo.removeAllItems();
        for (String o : opts) teleportCombo.addItem(o);
        String current = runLocation.getTeleportOption();
        if (current != null && opts.contains(current)) {
            teleportCombo.setSelectedItem(current);
        } else if (!opts.isEmpty()) {
            teleportCombo.setSelectedIndex(0);
            runLocation.setTeleportOption(opts.get(0));
        }
    }

    private void openCurrentStepTextEditor() {
        CurrentStepInstruction step = plugin.getCurrentStepInstruction();
        if (step == null || !locationName.equals(step.getLocationName())) {
            return;
        }
        if (step.getKind() == CurrentStepInstruction.Kind.NAVIGATION) {
            openNavigationTextEditor(step.getTeleportOption(), step.getDefaultText());
        } else {
            openFarmingStepTextEditor(step.getDefaultText());
        }
    }

    private void openFarmingStepTextEditor(String defaultText) {
        NavigationTextOverrides overrides = plugin.getNavigationTextOverrides();
        String currentText = overrides.resolveStep(defaultText);

        JTextArea textArea = new JTextArea(currentText, 5, 40);
        textArea.setLineWrap(true);
        textArea.setWrapStyleWord(true);
        JScrollPane scrollPane = new JScrollPane(textArea);

        JPanel panel = new JPanel(new BorderLayout(0, 8));
        panel.add(new JLabel("Step text for " + locationName), BorderLayout.NORTH);
        panel.add(scrollPane, BorderLayout.CENTER);

        Object[] options = {"Save", "Reset to default", "Cancel"};
        int result = JOptionPane.showOptionDialog(
                this,
                panel,
                "Edit step text",
                JOptionPane.YES_NO_CANCEL_OPTION,
                JOptionPane.PLAIN_MESSAGE,
                null,
                options,
                options[0]);

        if (result == 0) {
            String edited = textArea.getText() != null ? textArea.getText().trim() : "";
            String baseline = defaultText != null ? defaultText : "";
            if (edited.isEmpty() || edited.equals(baseline)) {
                overrides.clearStepOverride(defaultText);
            } else {
                overrides.setStepOverride(defaultText, edited);
            }
        } else if (result == 1) {
            overrides.clearStepOverride(defaultText);
        }
    }

    private void openNavigationTextEditor(String teleportOption, String defaultTextFromStep) {
        if (teleportOption == null) {
            Object selected = teleportCombo.getSelectedItem();
            if (selected == null) {
                return;
            }
            teleportOption = (String) selected;
        }
        Teleport teleport = findTeleport(teleportOption);
        if (teleport == null) {
            JOptionPane.showMessageDialog(
                    this,
                    "Could not find teleport details for " + teleportOption.replace('_', ' ') + ".",
                    "Edit step text",
                    JOptionPane.WARNING_MESSAGE);
            return;
        }

        NavigationTextOverrides overrides = plugin.getNavigationTextOverrides();
        String defaultText = defaultTextFromStep != null && !defaultTextFromStep.isEmpty()
                ? defaultTextFromStep
                : (teleport.getDescription() != null ? teleport.getDescription() : "");
        String currentText = overrides.resolve(locationName, teleport);

        JTextArea textArea = new JTextArea(currentText, 5, 40);
        textArea.setLineWrap(true);
        textArea.setWrapStyleWord(true);
        JScrollPane scrollPane = new JScrollPane(textArea);

        JPanel panel = new JPanel(new BorderLayout(0, 8));
        panel.add(new JLabel("Navigation text for " + locationName + " · " + teleportOption.replace('_', ' ')), BorderLayout.NORTH);
        panel.add(scrollPane, BorderLayout.CENTER);

        Object[] options = {"Save", "Reset to default", "Cancel"};
        int result = JOptionPane.showOptionDialog(
                this,
                panel,
                "Edit step text",
                JOptionPane.YES_NO_CANCEL_OPTION,
                JOptionPane.PLAIN_MESSAGE,
                null,
                options,
                options[0]);

        if (result == 0) {
            String edited = textArea.getText() != null ? textArea.getText().trim() : "";
            if (edited.isEmpty() || edited.equals(defaultText)) {
                overrides.clearOverride(locationName, teleportOption);
            } else {
                overrides.setOverride(locationName, teleportOption, edited);
            }
        } else if (result == 1) {
            overrides.clearOverride(locationName, teleportOption);
        }
    }

    private Teleport findTeleport(String teleportOption) {
        LocationCatalog catalog = plugin.getLocationCatalog();
        List<String> patchTypes = runLocation.getPatchTypes();
        if (patchTypes != null) {
            for (String patchType : patchTypes) {
                Location loc = catalog.getLocationForPatch(locationName, patchType);
                Teleport match = findTeleportOnLocation(loc, teleportOption);
                if (match != null) {
                    return match;
                }
            }
        }
        List<String> available = catalog.getPatchTypesAtLocation(locationName);
        if (available != null) {
            for (String patchType : available) {
                Location loc = catalog.getLocationForPatch(locationName, patchType);
                Teleport match = findTeleportOnLocation(loc, teleportOption);
                if (match != null) {
                    return match;
                }
            }
        }
        return null;
    }

    private static Teleport findTeleportOnLocation(Location loc, String teleportOption) {
        if (loc == null || teleportOption == null) {
            return null;
        }
        for (Teleport teleport : loc.getTeleportOptions()) {
            if (teleportOption.equals(teleport.getEnumOption())) {
                return teleport;
            }
        }
        return null;
    }

    private void refreshPatchIcons() {
        patchIconsPanel.removeAll();
        LocationCatalog catalog = plugin.getLocationCatalog();
        List<String> available = catalog.getPatchTypesAtLocation(locationName);
        if (available == null) {
            available = new ArrayList<>();
        }
        List<String> selected = runLocation.getPatchTypes() != null
                ? runLocation.getPatchTypes()
                : new ArrayList<>();

        // Selected patches first in visit order, then unselected available types.
        List<String> displayOrder = new ArrayList<>();
        for (String patchType : selected) {
            if (available.contains(patchType)) {
                displayOrder.add(patchType);
            }
        }
        for (String patchType : available) {
            if (!selected.contains(patchType)) {
                displayOrder.add(patchType);
            }
        }

        boolean canReorder = selected.size() > 1;
        for (String patchType : displayOrder) {
            boolean isSelected = selected.contains(patchType);
            patchIconsPanel.add(makePatchIconButton(patchType, isSelected, canReorder && isSelected));
        }
        patchIconsPanel.revalidate();
        patchIconsPanel.repaint();
    }

    public void refreshFromRunLocation() {
        refreshingFromRun = true;
        try {
            refreshTeleportOptions();
            refreshPatchIcons();
        } finally {
            refreshingFromRun = false;
        }
    }

    private JButton makePatchIconButton(String patchType, boolean selected, boolean draggable) {
        int itemId = itemIdForPatchType(patchType);
        String tooltip = displayName(patchType);
        if (draggable) {
            tooltip = tooltip + " — drag to reorder visit order";
        }
        JButton btn = new JButton();
        btn.putClientProperty(CLIENT_PROP_PATCH_TYPE, patchType);
        btn.setPreferredSize(new Dimension(PATCH_ICON_SIZE, PATCH_ICON_SIZE));
        btn.setFocusable(false);
        btn.setToolTipText(tooltip);
        btn.setBackground(selected ? new Color(30, 60, 30) : ColorScheme.DARKER_GRAY_COLOR);
        btn.setForeground(Color.WHITE);
        btn.setOpaque(true);
        btn.setBorderPainted(false);
        if (draggable) {
            btn.setCursor(new Cursor(Cursor.MOVE_CURSOR));
        }
        if (itemManager != null) {
            itemManager.getImage(itemId).addTo(btn);
        } else {
            btn.setText(displayName(patchType));
        }

        btn.addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                if (!SwingUtilities.isLeftMouseButton(e)) {
                    return;
                }
                patchDragPressPoint = e.getPoint();
                patchDragMoved = false;
                draggedPatchType = draggable ? patchType : null;
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                if (!SwingUtilities.isLeftMouseButton(e)) {
                    return;
                }
                try {
                    if (draggedPatchType != null && patchDragMoved) {
                        String dropBefore = findPatchTypeAtScreenPoint(e.getLocationOnScreen());
                        if (dropBefore != null && !dropBefore.equals(draggedPatchType)) {
                            reorderPatch(draggedPatchType, dropBefore);
                        }
                    } else if (!patchDragMoved) {
                        togglePatchType(patchType);
                    }
                } finally {
                    draggedPatchType = null;
                    patchDragPressPoint = null;
                    patchDragMoved = false;
                }
            }
        });
        btn.addMouseMotionListener(new MouseAdapter() {
            @Override
            public void mouseDragged(MouseEvent e) {
                if (draggedPatchType == null || patchDragPressPoint == null) {
                    return;
                }
                int dx = e.getX() - patchDragPressPoint.x;
                int dy = e.getY() - patchDragPressPoint.y;
                if (Math.abs(dx) + Math.abs(dy) >= PATCH_DRAG_THRESHOLD_PX) {
                    patchDragMoved = true;
                }
            }
        });
        return btn;
    }

    private String findPatchTypeAtScreenPoint(Point screenPoint) {
        Point inPanel = new Point(screenPoint);
        SwingUtilities.convertPointFromScreen(inPanel, patchIconsPanel);
        Component at = patchIconsPanel.getComponentAt(inPanel);
        while (at != null && at != patchIconsPanel) {
            Object prop = (at instanceof JComponent)
                    ? ((JComponent) at).getClientProperty(CLIENT_PROP_PATCH_TYPE)
                    : null;
            if (prop instanceof String) {
                List<String> selected = runLocation.getPatchTypes();
                if (selected != null && selected.contains((String) prop)) {
                    return (String) prop;
                }
                return null;
            }
            at = at.getParent();
        }
        return null;
    }

    private void togglePatchType(String patchType) {
        if (refreshingFromRun) {
            return;
        }
        List<String> types = runLocation.getPatchTypes();
        if (types == null) {
            types = new ArrayList<>();
            runLocation.setPatchTypes(types);
        }
        if (types.contains(patchType)) {
            types.remove(patchType);
        } else {
            types.add(patchType);
        }
        refreshPatchIcons();
        if (onChanged != null) {
            onChanged.run();
        }
    }

    /**
     * Moves {@code movedType} so it appears immediately before {@code dropBeforeType} in visit order.
     * Package-visible for unit tests.
     */
    static void reorderPatchTypes(List<String> types, String movedType, String dropBeforeType) {
        if (types == null || movedType == null || dropBeforeType == null) {
            return;
        }
        if (!types.contains(movedType) || !types.contains(dropBeforeType) || movedType.equals(dropBeforeType)) {
            return;
        }
        types.remove(movedType);
        int insertIndex = types.indexOf(dropBeforeType);
        if (insertIndex < 0) {
            types.add(movedType);
        } else {
            types.add(insertIndex, movedType);
        }
    }

    private void reorderPatch(String movedType, String dropBeforeType) {
        List<String> types = runLocation.getPatchTypes();
        if (types == null) {
            return;
        }
        reorderPatchTypes(types, movedType, dropBeforeType);
        refreshPatchIcons();
        if (onChanged != null) {
            onChanged.run();
        }
    }

    private static int itemIdForPatchType(String patchType) {
        switch (patchType) {
            case PatchTypes.HERB: return GRIMY_RANARR_WEED;
            case PatchTypes.FLOWER: return net.runelite.api.gameval.ItemID.LIMPWURT_ROOT;
            case PatchTypes.ALLOTMENT: return net.runelite.api.gameval.ItemID.WATERMELON;
            case PatchTypes.TREE: return net.runelite.api.gameval.ItemID.YEW_LOGS;
            case PatchTypes.FRUIT_TREE: return net.runelite.api.gameval.ItemID.PINEAPPLE;
            case PatchTypes.HOPS: return net.runelite.api.gameval.ItemID.BARLEY;
            default: return GRIMY_RANARR_WEED;
        }
    }

    private static String displayName(String patchType) {
        switch (patchType) {
            case PatchTypes.HERB: return "Herb";
            case PatchTypes.FLOWER: return "Flower";
            case PatchTypes.ALLOTMENT: return "Allotment";
            case PatchTypes.TREE: return "Tree";
            case PatchTypes.FRUIT_TREE: return "Fruit tree";
            case PatchTypes.HOPS: return "Hops";
            default: return patchType.replace("_", " ");
        }
    }
}

package com.easyfarming.ui;

import com.easyfarming.EasyFarmingPlugin;
import com.easyfarming.EasyFarmingPanel;
import com.easyfarming.StartStopJButton;
import com.easyfarming.customrun.CustomRun;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;

/**
 * One custom run row in the overview: name + Start, click to open detail.
 */
public class CustomRunOverviewRow extends JPanel {
    private final EasyFarmingPlugin plugin;
    private final EasyFarmingPanel parentPanel;
    private final CustomRun customRun;
    private final StartStopJButton startStopButton;

    public CustomRunOverviewRow(EasyFarmingPlugin plugin, EasyFarmingPanel parentPanel, CustomRun customRun) {
        this.plugin = plugin;
        this.parentPanel = parentPanel;
        this.customRun = customRun;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setBorder(new EmptyBorder(10, 10, 10, 10));

        startStopButton = new StartStopJButton(customRun.getName());
        startStopButton.setPreferredSize(new Dimension(80, 25));
        startStopButton.addActionListener(e -> {
            boolean toggleToStop = startStopButton.getText().equals("Start");
            startStopButton.setStartStopState(toggleToStop);
            if (toggleToStop) {
                parentPanel.startCustomRun(customRun);
            } else {
                plugin.getFarmingTeleportOverlay().removeOverlay();
                plugin.setOverlayActive(false);
            }
        });
        syncStartButtonState();

        JPanel container = new JPanel(new BorderLayout());
        container.setOpaque(false);
        JLabel nameLabel = new JLabel(customRun.getName() != null ? customRun.getName() : "New Run");
        nameLabel.setForeground(Color.WHITE);
        nameLabel.setFont(net.runelite.client.ui.FontManager.getRunescapeBoldFont());
        container.add(nameLabel, BorderLayout.WEST);
        container.add(startStopButton, BorderLayout.EAST);
        add(container, BorderLayout.CENTER);

        MouseAdapter mouseAdapter = new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
                setCursor(new Cursor(Cursor.HAND_CURSOR));
            }

            @Override
            public void mouseExited(MouseEvent e) {
                setBackground(ColorScheme.DARKER_GRAY_COLOR);
                setCursor(new Cursor(Cursor.DEFAULT_CURSOR));
            }

            @Override
            public void mousePressed(MouseEvent e) {
                if (SwingUtilities.isLeftMouseButton(e)) {
                    Component src = (Component) e.getSource();
                    if (src == startStopButton || SwingUtilities.isDescendingFrom(src, startStopButton)) {
                        return;
                    }
                    parentPanel.showRunDetail(customRun);
                } else if (SwingUtilities.isRightMouseButton(e)) {
                    showContextMenu(e);
                }
            }
        };
        addMouseListener(mouseAdapter);
        nameLabel.addMouseListener(mouseAdapter);
        container.addMouseListener(mouseAdapter);
    }

    private void showContextMenu(MouseEvent e) {
        JPopupMenu popup = new JPopupMenu();
        JMenuItem renameItem = new JMenuItem("Rename");
        renameItem.addActionListener(ev -> renameRun());
        popup.add(renameItem);
        JMenuItem deleteItem = new JMenuItem("Delete");
        deleteItem.addActionListener(ev -> deleteRun());
        popup.add(deleteItem);
        popup.show(e.getComponent(), e.getX(), e.getY());
    }

    private void renameRun() {
        String currentName = customRun.getName() != null ? customRun.getName() : "";
        String newName = (String) JOptionPane.showInputDialog(this, "Run name:", "Rename custom run", JOptionPane.PLAIN_MESSAGE, null, null, currentName);
        if (newName == null) return;
        newName = newName.trim();
        if (newName.isEmpty()) return;
        customRun.setName(newName);
        plugin.getCustomRunStorage().save(plugin.getCustomRunStorage().load());
        parentPanel.refreshOverviewList();
    }

    private void deleteRun() {
        int confirm = JOptionPane.showConfirmDialog(this,
                "Delete \"" + (customRun.getName() != null ? customRun.getName() : "run") + "\"?",
                "Delete custom run",
                JOptionPane.YES_NO_OPTION,
                JOptionPane.WARNING_MESSAGE);
        if (confirm != JOptionPane.YES_OPTION) return;
        List<CustomRun> runs = plugin.getCustomRunStorage().load();
        runs.removeIf(r -> r == customRun || (customRun.getName() != null && customRun.getName().equals(r.getName())));
        plugin.getCustomRunStorage().save(runs);
        parentPanel.refreshOverviewList();
    }

    private void syncStartButtonState() {
        if (plugin.getFarmingTeleportOverlay().isCustomRunMode()
                && customRun.getName() != null
                && customRun.getName().equals(plugin.getFarmingTeleportOverlay().getActiveCustomRunName())) {
            startStopButton.setStartStopState(true);
        }
    }
}

package com.easyfarming.ui;

import com.easyfarming.core.Location;
import com.easyfarming.core.Teleport;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

/**
 * One location row in the run detail view (same style as LocationConfigPanel):
 * collapsible header with location name, body with teleport dropdown.
 * Uses master's Location only; teleport dropdown shows options and current selection.
 */
public class LocationRowPanel extends JPanel {
    private final Location location;
    private final JPanel headerPanel;
    private final JPanel mainBodyContainer;
    private boolean isExpanded = true;
    private final JLabel toggleLabel;

    public LocationRowPanel(Location location) {
        this.location = location;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setBorder(BorderFactory.createMatteBorder(1, 1, 1, 1, ColorScheme.DARK_GRAY_COLOR));

        headerPanel = new JPanel(new BorderLayout());
        headerPanel.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
        headerPanel.setBorder(new EmptyBorder(5, 10, 5, 10));

        JLabel nameLabel = new JLabel(location.getName());
        nameLabel.setFont(FontManager.getRunescapeBoldFont());
        nameLabel.setForeground(Color.WHITE);
        headerPanel.add(nameLabel, BorderLayout.WEST);

        JPanel controlsPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 5, 0));
        controlsPanel.setOpaque(false);
        toggleLabel = new JLabel("−");
        toggleLabel.setFont(FontManager.getRunescapeBoldFont());
        toggleLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        toggleLabel.setCursor(new Cursor(Cursor.HAND_CURSOR));
        controlsPanel.add(toggleLabel);
        headerPanel.add(controlsPanel, BorderLayout.EAST);
        add(headerPanel, BorderLayout.NORTH);

        mainBodyContainer = new JPanel(new BorderLayout());
        mainBodyContainer.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        mainBodyContainer.setBorder(new EmptyBorder(10, 10, 10, 10));

        List<String> teleportNames = location.getTeleportOptions() == null
                ? new ArrayList<>()
                : location.getTeleportOptions().stream()
                        .map(Teleport::getEnumOption)
                        .collect(Collectors.toList());

        if (!teleportNames.isEmpty()) {
            JPanel telePanel = new JPanel(new BorderLayout());
            telePanel.setOpaque(false);
            telePanel.setBorder(new EmptyBorder(10, 0, 0, 0));
            JLabel teleLabel = new JLabel("Teleport");
            teleLabel.setForeground(Color.WHITE);
            JComboBox<String> teleCombo = new JComboBox<>(teleportNames.toArray(new String[0]));
            teleCombo.setRenderer(new DefaultListCellRenderer() {
                @Override
                public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus) {
                    Component c = super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
                    if (value != null) {
                        ((JLabel) c).setText(((String) value).replace("_", " "));
                    }
                    return c;
                }
            });
            Teleport selected = location.getSelectedTeleport();
            if (selected != null) {
                teleCombo.setSelectedItem(selected.getEnumOption());
            } else {
                teleCombo.setSelectedIndex(0);
            }
            teleCombo.addActionListener(e -> {
                Object sel = teleCombo.getSelectedItem();
                if (sel instanceof String) {
                    location.setOverrideTeleportEnumOption((String) sel);
                }
            });
            telePanel.add(teleLabel, BorderLayout.WEST);
            telePanel.add(teleCombo, BorderLayout.EAST);
            mainBodyContainer.add(telePanel, BorderLayout.SOUTH);
        }

        add(mainBodyContainer, BorderLayout.CENTER);

        MouseAdapter toggleAdapter = new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                isExpanded = !isExpanded;
                mainBodyContainer.setVisible(isExpanded);
                toggleLabel.setText(isExpanded ? "−" : "+");
                revalidate();
                repaint();
            }
        };
        headerPanel.addMouseListener(toggleAdapter);
        nameLabel.addMouseListener(toggleAdapter);
        toggleLabel.addMouseListener(toggleAdapter);
    }

    public JPanel getHeaderPanel() {
        return headerPanel;
    }
}

package com.easyfarming.ui;

import com.easyfarming.EasyFarmingPlugin;
import com.easyfarming.EasyFarmingPanel;
import com.easyfarming.customrun.CustomRun;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.List;

/**
 * Overview list: "Custom runs" section with saved custom runs and "+ New custom run" card.
 *
 * When a custom run is active, a "Skip step" button is rendered at the top so the user has
 * an escape hatch when the plugin is stuck on a step (e.g. varbit state the plugin cannot
 * classify, or the user intentionally skipped a patch). See issue #98.
 */
public class OverviewPanel extends JPanel {
    private final EasyFarmingPlugin plugin;
    private final EasyFarmingPanel parentPanel;
    private final JPanel contentPanel;
    private boolean creatingRun;

    public OverviewPanel(EasyFarmingPlugin plugin, EasyFarmingPanel parentPanel) {
        this.plugin = plugin;
        this.parentPanel = parentPanel;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        contentPanel = new JPanel();
        contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
        contentPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        contentPanel.setBorder(new EmptyBorder(10, 10, 10, 10));

        rebuildList();

        add(contentPanel, BorderLayout.NORTH);
    }

    public void rebuildList() {
        contentPanel.removeAll();

        // Active-run controls: Skip step button (issue #98). Rendered above the run list
        // when a custom run is active. Hidden otherwise to avoid clutter.
        if (plugin.getFarmingTeleportOverlay() != null
                && plugin.getFarmingTeleportOverlay().isCustomRunMode()) {
            JButton skipButton = new JButton("Skip current step");
            skipButton.setFocusable(false);
            skipButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            skipButton.setForeground(Color.WHITE);
            skipButton.setAlignmentX(Component.LEFT_ALIGNMENT);
            skipButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, skipButton.getPreferredSize().height));
            skipButton.setToolTipText("Skip the current step: item checklist, travel, or farming.");
            skipButton.addActionListener(e -> plugin.skipCurrentStep());
            contentPanel.add(skipButton);
            contentPanel.add(Box.createRigidArea(new Dimension(0, 10)));
        }

        JPanel customTitlePanel = new JPanel(new BorderLayout());
        customTitlePanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        customTitlePanel.setBorder(new EmptyBorder(0, 0, 8, 0));
        JLabel customTitle = new JLabel("Custom runs:");
        customTitle.setForeground(Color.WHITE);
        customTitlePanel.add(customTitle, BorderLayout.WEST);
        contentPanel.add(customTitlePanel);

        List<CustomRun> customRuns = plugin.getCustomRunStorage().load();
        for (CustomRun run : customRuns) {
            contentPanel.add(new CustomRunOverviewRow(plugin, parentPanel, run));
            contentPanel.add(Box.createRigidArea(new Dimension(0, 10)));
        }

        JPanel addCard = new JPanel(new BorderLayout());
        addCard.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        addCard.setBorder(new EmptyBorder(10, 10, 10, 10));
        JLabel addLabel = new JLabel("+ New custom run");
        addLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        addCard.add(addLabel, BorderLayout.CENTER);
        addCard.setCursor(new Cursor(Cursor.HAND_CURSOR));
        addCard.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override
            public void mouseClicked(java.awt.event.MouseEvent e) {
                if (creatingRun) {
                    return;
                }
                creatingRun = true;
                try {
                    String name = (String) JOptionPane.showInputDialog(
                            OverviewPanel.this,
                            "Enter a name for the new run:",
                            "New custom run",
                            JOptionPane.PLAIN_MESSAGE,
                            null,
                            null,
                            "New Run");
                    if (name == null) return;
                    name = name.trim();
                    if (name.isEmpty()) name = "New Run";
                    CustomRun newRun = new CustomRun(name, new java.util.ArrayList<>());
                    List<CustomRun> runs = plugin.getCustomRunStorage().load();
                    runs.add(newRun);
                    plugin.getCustomRunStorage().save(runs);
                    parentPanel.showRunDetail(newRun);
                } finally {
                    creatingRun = false;
                }
            }
        });
        contentPanel.add(addCard);

        revalidate();
        repaint();
    }
}

package com.easyfarming.ui.components;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Insets;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;

/**
 * FlowLayout subclass that fully supports wrapping of components.
 */
public class WrapLayout extends FlowLayout {

    public WrapLayout() {
        super();
    }

    public WrapLayout(int align) {
        super(align);
    }

    public WrapLayout(int align, int hgap, int vgap) {
        super(align, hgap, vgap);
    }

    @Override
    public Dimension preferredLayoutSize(Container target) {
        return layoutSize(target, true);
    }

    @Override
    public Dimension minimumLayoutSize(Container target) {
        Dimension minimum = layoutSize(target, false);
        minimum.width -= (getHgap() + 1);
        return minimum;
    }

    private Dimension layoutSize(Container target, boolean preferred) {
        synchronized (target.getTreeLock()) {
            int targetWidth = target.getSize().width;
            Container container = target;

            while (container.getSize().width == 0 && container.getParent() != null) {
                container = container.getParent();
            }

            targetWidth = container.getSize().width;

            if (targetWidth == 0) {
                targetWidth = Integer.MAX_VALUE;
            }

            int hgap = getHgap();
            int vgap = getVgap();
            Insets insets = target.getInsets();
            int horizontalInsetsAndGap = insets.left + insets.right + (hgap * 2);
            int maxWidth = targetWidth - horizontalInsetsAndGap;

            Dimension dim = new Dimension(0, 0);
            int rowWidth = 0;
            int rowHeight = 0;

            int nmembers = target.getComponentCount();

            for (int i = 0; i < nmembers; i++) {
                Component m = target.getComponent(i);

                if (m.isVisible()) {
                    Dimension d = preferred ? m.getPreferredSize() : m.getMinimumSize();

                    if (rowWidth + d.width > maxWidth) {
                        addRow(dim, rowWidth, rowHeight);
                        rowWidth = 0;
                        rowHeight = 0;
                    }

                    if (rowWidth != 0) {
                        rowWidth += hgap;
                    }

                    rowWidth += d.width;
                    rowHeight = Math.max(rowHeight, d.height);
                }
            }

            addRow(dim, rowWidth, rowHeight);

            dim.width += horizontalInsetsAndGap;
            dim.height += insets.top + insets.bottom + vgap * 2;

            Container scrollPane = SwingUtilities.getAncestorOfClass(JScrollPane.class, target);
            if (scrollPane != null && target.isValid()) {
                dim.width -= (hgap + 1);
            }

            return dim;
        }
    }

    private void addRow(Dimension dim, int rowWidth, int rowHeight) {
        dim.width = Math.max(dim.width, rowWidth);
        if (dim.height > 0) {
            dim.height += getVgap();
        }
        dim.height += rowHeight;
    }
}

