package com.easyfarming.overlays.handlers;

import com.easyfarming.utils.Constants;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Region → tree location mapping used for patch anchors and hint arrows.
 * Wrong mapping at Falador Park previously pointed the REMOVE-step arrow at Taverley
 * instead of Heskel (issue #101).
 */
public class FarmingStepHandlerTreeRegionTest {

    @Test
    public void faladorParkRegionMapsToFaladorNotTaverley() {
        // RuneLite FarmingWorld: Falador TREE primary 11828, extra 12084
        assertEquals("Falador", FarmingStepHandler.getTreeLocationNameFromRegionId(Constants.REGION_FALADOR_PARK));
        assertEquals("Falador", FarmingStepHandler.getTreeLocationNameFromRegionId(Constants.REGION_FALADOR_PARK_ALT));
        assertEquals("Falador", FarmingStepHandler.getTreeLocationNameFromRegionId(11828));
        assertEquals("Falador", FarmingStepHandler.getTreeLocationNameFromRegionId(12084));
    }

    @Test
    public void taverleyRegionMapsToTaverley() {
        // RuneLite FarmingWorld: Taverley TREE primary 11573, extra 11829
        assertEquals("Taverley", FarmingStepHandler.getTreeLocationNameFromRegionId(Constants.REGION_TAVERLEY));
        assertEquals("Taverley", FarmingStepHandler.getTreeLocationNameFromRegionId(Constants.REGION_TAVERLEY_ALT));
        assertEquals("Taverley", FarmingStepHandler.getTreeLocationNameFromRegionId(11573));
        assertEquals("Taverley", FarmingStepHandler.getTreeLocationNameFromRegionId(11829));
    }

    @Test
    public void faladorHerbRegionStillMapsToFalador() {
        assertEquals("Falador", FarmingStepHandler.getTreeLocationNameFromRegionId(Constants.REGION_FALADOR));
    }

    @Test
    public void unknownRegionReturnsNull() {
        assertNull(FarmingStepHandler.getTreeLocationNameFromRegionId(0));
    }
}

package com.easyfarming.overlays.highlighting;

import net.runelite.api.Point;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Multi-tile GameObjects are present on every occupied tile; only the SW/min tile is the
 * highlight anchor (RuneLite DevToolsOverlay pattern). Without this filter, allotment/hops
 * patches redraw overlapping clickboxes and tank FPS (issue #101).
 */
public class GameObjectHighlighterAnchorTileTest {

    @Test
    public void anchorTileMatchesSceneMinLocation() {
        Point min = new Point(10, 20);
        assertTrue(GameObjectHighlighter.isGameObjectAnchorTile(min, new Point(10, 20)));
    }

    @Test
    public void nonAnchorOccupiedTileIsRejected() {
        Point min = new Point(10, 20);
        assertFalse(GameObjectHighlighter.isGameObjectAnchorTile(min, new Point(11, 20)));
        assertFalse(GameObjectHighlighter.isGameObjectAnchorTile(min, new Point(10, 21)));
        assertFalse(GameObjectHighlighter.isGameObjectAnchorTile(min, new Point(12, 22)));
    }

    @Test
    public void nullLocationsAreRejected() {
        assertFalse(GameObjectHighlighter.isGameObjectAnchorTile(null, new Point(0, 0)));
        assertFalse(GameObjectHighlighter.isGameObjectAnchorTile(new Point(0, 0), null));
        assertFalse(GameObjectHighlighter.isGameObjectAnchorTile(null, null));
    }
}

package com.easyfarming.ui;

import com.easyfarming.customrun.PatchTypes;
import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertEquals;

/**
 * Visit order for multi-patch locations is {@code RunLocation.patchTypes} list order (#101).
 */
public class CustomRunPatchReorderTest {

    @Test
    public void reorderMovesPatchBeforeDropTarget() {
        List<String> types = new ArrayList<>(Arrays.asList(PatchTypes.TREE, PatchTypes.FRUIT_TREE));
        CustomRunLocationSubPanel.reorderPatchTypes(types, PatchTypes.FRUIT_TREE, PatchTypes.TREE);
        assertEquals(Arrays.asList(PatchTypes.FRUIT_TREE, PatchTypes.TREE), types);
    }

    @Test
    public void reorderNoopsWhenTypesMissingOrSame() {
        List<String> types = new ArrayList<>(Arrays.asList(PatchTypes.TREE, PatchTypes.FRUIT_TREE, PatchTypes.HERB));
        CustomRunLocationSubPanel.reorderPatchTypes(types, PatchTypes.TREE, PatchTypes.TREE);
        assertEquals(Arrays.asList(PatchTypes.TREE, PatchTypes.FRUIT_TREE, PatchTypes.HERB), types);

        CustomRunLocationSubPanel.reorderPatchTypes(types, PatchTypes.HOPS, PatchTypes.TREE);
        assertEquals(Arrays.asList(PatchTypes.TREE, PatchTypes.FRUIT_TREE, PatchTypes.HERB), types);
    }

    @Test
    public void reorderMiddlePatchBeforeEarlier() {
        List<String> types = new ArrayList<>(Arrays.asList(
                PatchTypes.HERB, PatchTypes.FLOWER, PatchTypes.ALLOTMENT));
        CustomRunLocationSubPanel.reorderPatchTypes(types, PatchTypes.ALLOTMENT, PatchTypes.HERB);
        assertEquals(Arrays.asList(PatchTypes.ALLOTMENT, PatchTypes.HERB, PatchTypes.FLOWER), types);
    }
}

